INSERT INTO public.leyes (id,siglas,titulo,tipo,fecha_publicacion,vigente,url_original,temas_clave) VALUES ('bc88f14b-069f-56d9-b9a9-6456e808561d','SCJN-CC-120-2026','SENTENCIA dictada por el Tribunal Pleno de la Suprema Corte de Justicia de la Nación en la Controversia Constitucional 120/2026, así como el Voto Concurrente de la señora Ministra Lenia Batres Guadarrama.','sentencia','2026-11-17',NULL,'https://sidof.segob.gob.mx/notas/5803873',ARRAY['Castaños, Coahuila','SCJN','Competencias federales','Cobros municipales','Energía eléctrica','Hidrocarburos']);
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('11cea9ed-1ff0-5a22-9ce6-afdee7f28806','bc88f14b-069f-56d9-b9a9-6456e808561d','Ficha y problemas jurídicos','<h1> SENTENCIA dictada por el Tribunal Pleno de la Suprema Corte de Justicia de la Nación en la Controversia Constitucional 120/2026, así como el Voto Concurrente de la señora Ministra Lenia Batres Guadarrama.</h1>
<h2> Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Suprema Corte de Justicia de la Nación.- Secretaría General de Acuerdos.</h2>
<div> CONTROVERSIA CONSTITUCIONAL 120/2026</div>
<div> ACTOR: PODER EJECUTIVO FEDERAL</div>
<div> PONENTE: MINISTRA YASMÍN ESQUIVEL MOSSA</div>
<div> COTEJÓ</div>
<div> SECRETARIOS:        GUADALUPE DE LA PAZ VARELA DOMÍNGUEZ</div>
<div>                      RODRIGO ARTURO CUEVAS Y MEDINA</div>
<div> Hechos: El Poder Ejecutivo Federal solicita la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3 de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial local el veintitrés de diciembre de dos mil veinticinco.</div>
<div> Problemas jurídicos que se plantean:</div>
<div> 1.- ¿El numeral 1 de la fracción VII del artículo 34 impugnado invade la competencia exclusiva de la Federación en materia de energía eléctrica, prevista en los artículos 25, párrafo quinto; 27, párrafo sexto; 28, párrafos cuarto y noveno; y 73, fracciones X y XXIX, numeral 5o., inciso a), de la Constitución Federal?</div>
<div> 2.- ¿Los numerales 2 y 3 de la fracción VII del artículo 34 impugnado invaden la competencia exclusiva de la Federación en materia de hidrocarburos, prevista en los artículos 25, párrafo quinto; 27, párrafos cuarto, sexto y séptimo; 28, párrafos cuarto y noveno; y 73, fracciones X y XXIX, numeral 2o., de la Constitución Federal?</div>','1','apartado','Ficha y problemas jurídicos','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('7340d653-c885-585a-a433-87b58884a3a7','bc88f14b-069f-56d9-b9a9-6456e808561d','Índice temático','<div> ÍNDICE TEMÁTICO<br/> </div>
<table>              <thead><tr> <th> <div>  </div> </th> <th> <div> Apartado<br/> </div> </th> <th> <div> Criterio y decisión<br/> </div> </th> <th> <div> Págs.<br/> </div> </th> </tr></thead><tbody><tr> <td> <div> I.<br/> </div> </td> <td> <div> COMPETENCIA<br/> </div> </td> <td> <div> El Tribunal Pleno es competente para conocer y resolver el presente asunto.</div> </td> <td> <div> 5-6<br/> </div> </td> </tr><tr> <td> <div> II.<br/> </div> </td> <td> <div> PRECISIÓN Y<br/> EXISTENCIA DEL ACTO<br/> IMPUGNADO<br/> </div> </td> <td> <div> Se precisa la norma impugnada, cuya existencia se acredita con su publicación oficial.</div> </td> <td> <div> 6-7<br/> </div> </td> </tr><tr> <td> <div> III.<br/> </div> </td> <td> <div> OPORTUNIDAD<br/> </div> </td> <td> <div> La demanda es oportuna, pues se presentó dentro del plazo legal de treinta días hábiles contado a partir del día siguiente al de la publicación de la norma impugnada.</div> </td> <td> <div> 7-9<br/> </div> </td> </tr><tr> <td> <div> IV.<br/> </div> </td> <td> <div> LEGITIMACIÓN<br/> </div> </td> <td> <div> Tiene legitimación activa el Poder Ejecutivo Federal, el cual comparece por conducto de su Consejera Jurídica, y actúa en nombre de la Federación.</div> <div> Tienen legitimación pasiva los Poderes Ejecutivo y Legislativo del Estado de Coahuila de Zaragoza.</div> <div> Son terceras interesadas las Cámaras de Diputados y de Senadores del Congreso de la Unión.</div> </td> <td> <div> 9-13<br/> </div> </td> </tr><tr> <td> <div> V.<br/> </div> </td> <td> <div> CAUSAS DE<br/> IMPROCEDENCIA Y<br/> SOBRESEIMIENTO<br/> </div> </td> <td> <div> Se desestima lo que alega el Ejecutivo local demandado, en el sentido de que se limitó a la promulgación y publicación de la norma impugnada, en términos de sus facultades constitucionales y legales, porque invariablemente forma parte del proceso legislativo.</div> </td> <td> <div> 13-14<br/> </div> </td> </tr><tr> <td> <div> VI.<br/> </div> </td> <td> <div> ESTUDIO DE FONDO<br/> </div> </td> <td> <div>  </div> </td> <td> <div> 14-50<br/> </div> </td> </tr><tr> <td> <div> VI.1<br/> </div> </td> <td> <div> Parámetro constitucional<br/> aplicable en materia de<br/> hidrocarburos<br/> </div> </td> <td> <div> Se desarrolla el parámetro constitucional y legal aplicable en materia de hidrocarburos, a partir de los artículos 25, párrafo quinto; 27, párrafos cuarto, sexto y séptimo; 28, párrafos cuarto y noveno; y 73, fracciones X y XXIX, numerales 2o. y 5o., inciso c), de la Constitución Federal. Asimismo, se precisa que la Ley del Sector Hidrocarburos reserva a las autoridades federales la regulación, planeación, autorización, supervisión y verificación de las actividades que integran dicha industria, incluyendo la distribución, comercialización y expendio al público de gas y petrolíferos.</div> </td> <td> <div> 20-29<br/> </div> </td> </tr><tr> <td> <div> VI.2<br/> </div> </td> <td> <div> Parámetro constitucional<br/> aplicable en materia de<br/> energía eléctrica<br/> </div> </td> <td> <div> Se desarrolla el parámetro constitucional y legal aplicable en materia de energía eléctrica, a partir de los artículos 25, párrafo quinto; 27, párrafo sexto; 28, párrafos cuarto y noveno; y 73, fracciones X y XXIX, numeral 5o., inciso a), de la Constitución Federal. Asimismo, se precisa que la planeación, control, regulación y supervisión del Sistema Eléctrico Nacional, así como de las actividades de generación, transmisión, distribución y comercialización de energía eléctrica, corresponden a las autoridades federales.</div> </td> <td> <div> 29-34<br/> </div> </td> </tr><tr> <td> <div> VI.3<br/> </div> </td> <td> <div> Alcance de las facultades<br/> municipales en materia<br/> hacendaria,<br/> administrativa y de<br/> licencias de<br/> funcionamiento<br/> </div> </td> <td> <div> Se desarrollan las facultades municipales previstas en el artículo 115 de la Constitución Federal en materia hacendaria, administrativa y de funcionamiento de establecimientos comerciales, y se precisa que dichas atribuciones no son absolutas, pues deben ejercerse en armonía con las competencias reservadas a la Federación, sin extenderse a la autorización, regulación, refrendo o cobro específico sobre actividades vinculadas con la industria de hidrocarburos o sobre infraestructura del sector eléctrico.</div> </td> <td> <div> 34-42<br/> </div> </td> </tr><tr> <td> <div> VI.4<br/> </div> </td> <td> <div> Análisis del caso<br/> concreto<br/> </div> </td> <td> <div> Es inconstitucional el numeral 1 de la fracción VII del artículo 34 impugnado, toda vez que establece un cobro anual por la expedición de licencia de funcionamiento respecto de edificaciones productoras de energía eléctrica, lo que incide en infraestructura vinculada con el sector eléctrico, materia cuya regulación, autorización, supervisión y verificación corresponde a la Federación.</div> <div> Asimismo, son inconstitucionales los numerales 2 y 3 de la fracción VII del artículo 34 impugnado, porque establecen cobros anuales por la expedición de licencias de funcionamiento respecto de edificaciones destinadas a la extracción de gas natural y gas no asociado, actividades que forman parte de la industria de hidrocarburos y cuya regulación corresponde de manera exclusiva a la Federación.</div> </td> <td> <div> 42-50<br/> </div> </td> </tr><tr> <td> <div> VII.<br/> </div> </td> <td> <div> EFECTOS<br/> </div> </td> <td> <div> Declaratoria de invalidez: Se declara la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial del Gobierno local el veintitrés de diciembre de dos mil veinticinco.</div> <div> Fecha en que surtirá efectos la invalidez. Esta declaratoria de invalidez surtirá sus efectos a partir de la notificación de los puntos resolutivos al Congreso del Estado de Coahuila de Zaragoza.</div> <div> Notificación al Municipio. Finalmente, deberá notificarse la presente sentencia al Municipio involucrado, por ser la autoridad encargada de la aplicación de la ley de ingresos cuya disposición ha sido invalidada.</div> </td> <td> <div> 50-51<br/> </div> </td> </tr><tr> <td> <div> VIII.<br/> </div> </td> <td> <div> DECISIÓN<br/> </div> </td> <td> <div> PRIMERO. Es procedente y fundada la presente controversia constitucional.</div> <div> SEGUNDO. Se declara la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial del Gobierno local el veintitrés de diciembre de dos mil veinticinco, la cual surtirá efectos a partir de la notificación de estos puntos resolutivos al Congreso del Estado de Coahuila de Zaragoza, por las razones y en los términos precisados en los apartados VI y VII de esta sentencia.</div> <div> TERCERO. Publíquese esta resolución en el Diario Oficial de la Federación, en el Periódico Oficial del Gobierno del Estado de Coahuila de Zaragoza y en el Semanario Judicial de la Federación y su Gaceta.</div> </td> <td> <div> 51-52<br/> </div> </td> </tr></tbody></table>','2','apartado','Índice temático','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('d1d5c6b0-dbbe-5ffe-adc9-c8797372c90a','bc88f14b-069f-56d9-b9a9-6456e808561d','Identificación y presentación de la sentencia','<div> CONTROVERSIA CONSTITUCIONAL 120/2026</div>
<div> ACTOR: PODER EJECUTIVO FEDERAL</div>
<div> VISTO BUENO</div>
<div> SRA. MINISTRA</div>
<div> PONENTE: MINISTRA YASMÍN ESQUIVEL MOSSA</div>
<div> COTEJÓ</div>
<div> SECRETARIOS:   GUADALUPE DE LA PAZ VARELA DOMÍNGUEZ</div>
<div>                      RODRIGO ARTURO CUEVAS Y MEDINA</div>
<div> Ciudad de México. El Tribunal Pleno de la Suprema Corte de Justicia de la Nación, en sesión correspondiente al cuatro de agosto de dos mil veintiséis, emite la siguiente:</div>
<div> SENTENCIA<br/> </div>
<div> Mediante la cual se resuelve la controversia constitucional 120/2026, promovida por el Poder Ejecutivo Federal, en contra de los Poderes Ejecutivo y Legislativo, ambos del Estado de Coahuila de Zaragoza, en la que solicita la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3 de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial local el veintitrés de diciembre de dos mil veinticinco.</div>','3','apartado','Identificación y presentación de la sentencia','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('387cb395-43c0-5bb6-9dc1-31145915a06d','bc88f14b-069f-56d9-b9a9-6456e808561d','ANTECEDENTES Y TRÁMITE DE LA DEMANDA','<div> ANTECEDENTES Y TRÁMITE DE LA DEMANDA<br/> </div>
<div> 1.       Presentación de la demanda. Mediante oficio presentado el dieciséis de febrero de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de este Alto Tribunal(1), Esthela Damián Peralta, en su carácter de Consejera Jurídica del Ejecutivo Federal, promovió demanda de controversia constitucional, en la que impugna lo siguiente:</div>
<div> "IV. Norma general, cuya invalidez se demanda, y el medio oficial en el cual se publicó</div>
<div> DECRETO 345.- Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en la segunda sección del periódico oficial número 102, el 23 de diciembre de 2025, cuyo contenido es el siguiente:</div>
<div> ARTÍCULO 34.- [...]."</div>
<div> 2.       Conceptos de invalidez. La parte actora expuso los conceptos de invalidez que estimó pertinentes, de cuyo contenido se dará cuenta en el estudio de fondo.</div>
<div> 3.       Preceptos constitucionales que se estiman violados. Los preceptos que el actor estima violados son los artículos 25, párrafo quinto; 27, párrafos cuarto y séptimo; 28, párrafo cuarto; 73, fracciones X y XXIX, numerales 2o. y 5o., inciso c) y 124, de la Constitución Política de los Estados Unidos Mexicanos.</div>
<div> 4.       Radicación y turno. Por acuerdo de Presidencia de diecinueve de febrero de dos mil veintiséis, se ordenó formar y registrar la presente controversia constitucional bajo el número de expediente 120/2026 y se turnó a la Ministra Yasmín Esquivel Mossa como instructora del procedimiento.</div>
<div> 5.       Admisión. Mediante proveído de veintitrés de febrero de dos mil veintiséis, la Ministra instructora admitió a trámite la controversia constitucional y ordenó emplazar como partes demandadas a los Poderes Legislativo y Ejecutivo del Estado de Coahuila de Zaragoza, para que, dentro del plazo de treinta días hábiles, rindieran su respectiva contestación; asimismo, reconoció como terceros interesados a las Cámaras de Diputados y de Senadores del Congreso de la Unión; y finalmente, ordenó correr traslado a la Fiscalía General de la República para que formulara lo que a su derecho conviniera.</div>
<div> 6.       Comparece la Cámara de Senadores del Congreso de la Unión (tercero interesado). Mediante oficio recibido el veintitrés de marzo de dos mil veintiséis, Laura Itzel Castillo Juárez, ostentándose como Presidenta de la Mesa Directiva de la Cámara de Senadores del Congreso de la Unión, compareció a la presente controversia, señaló domicilio para oír y recibir notificaciones en esta ciudad y, finalmente, designó delegados, lo cual se tuvo por acordado de manera favorable en proveído de veinticuatro de marzo siguiente.</div>
<div> 7.       Manifestaciones de la Cámara de Senadores del Congreso de la Unión (tercero interesado). Por oficio recibido el veintiséis de marzo de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de la Suprema Corte de Justicia de la Nación(2), Sergio Ruiz Arias, en su carácter de delegado autorizado de la Cámara de Senadores del Congreso de la Unión, realizó manifestaciones en su carácter de tercero interesado, en las cuales solicita, en esencia, se declaren fundados los conceptos de invalidez formulados por el Ejecutivo Federal.</div>
<div> 8.       Manifestaciones de la Cámara de Diputados del Congreso de la Unión (tercero interesado). Por oficio recibido el dieciséis de abril de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de la Suprema Corte de Justicia de la Nación(3), Kenia López Rabadán, ostentándose como Presidenta de la Mesa Directiva de la Cámara de Diputados del Congreso de la Unión, realizó manifestaciones en su carácter de tercero interesado, en las cuales solicita, en esencia, se declaren fundados los conceptos de invalidez formulados por el Ejecutivo Federal.</div>
<div> 9.       Contestación del Poder Ejecutivo del Estado de Coahuila de Zaragoza. Mediante oficio recibido el veintisiete de mayo de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de la Suprema Corte de Justicia de la Nación(4), Juan Pablo Alvarado Cepeda, en su carácter de Consejero Jurídico del Gobierno del Estado de Coahuila de Zaragoza, formuló contestación a la demanda, en la que manifestó, en esencia:</div>
<div> ·   La intervención del Poder Ejecutivo del Estado dentro del procedimiento legislativo se limitó a la promulgación y publicación de la ley impugnada, en ejercicio de sus facultades constitucionales y legales, sin que se le atribuya de forma directa algún acto violatorio o concepto de invalidez vinculado con dichos actos.</div>
<div> 10.     Contestación del Poder Legislativo del Estado de Coahuila de Zaragoza. Mediante oficio recibido el veintisiete de mayo de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de la Suprema Corte de Justicia de la Nación(5), César Mario Esquivel Flores, en su carácter de Director de Asuntos Jurídicos del Congreso del Estado de Coahuila de Zaragoza, formuló contestación a la demanda, en la que manifestó, en esencia:</div>
<div>          En cuanto al fondo.</div>
<div> ·   La norma impugnada no regula la industria de hidrocarburos ni la generación de energía eléctrica, sino que establece derechos vinculados con licencias, permisos, autorizaciones y servicios de control ambiental dentro del ámbito competencial municipal.</div>
<div> ·   El artículo 115 constitucional faculta a los Municipios para autorizar, controlar y vigilar el uso de suelo, así como otorgar licencias y permisos de construcción, por lo que la disposición impugnada constituye una manifestación válida de esas atribuciones y no una invasión a competencias federales.</div>
<div> ·   La licencia de funcionamiento controvertida no sustituye permisos o autorizaciones federales ni regula aspectos técnicos de la industria energética o de hidrocarburos, sino que persigue finalidades de ordenamiento territorial, desarrollo urbano y control ambiental.</div>
<div> ·   La norma debe interpretarse en el contexto de las atribuciones municipales de protección ambiental y del deber estatal de garantizar el derecho humano a un medio ambiente sano, por lo que resulta compatible con el principio de distribución de competencias previsto en la Constitución.</div>
<div> 11.     Opinión de la Fiscalía General de la República. La citada dependencia no formuló manifestación o pedimento alguno.</div>
<div> 12.     Audiencia. Agotado el trámite respectivo, el nueve de julio de dos mil veintiséis tuvo verificativo la audiencia prevista en el artículo 29 de la Ley Reglamentaria de las Fracciones I y II del Artículo 105 de la Constitución Federal; y por acuerdo de la Ministra instructora del mismo día, se tuvo por cerrada la instrucción del procedimiento a efecto de elaborar el proyecto de resolución correspondiente; presentada la propuesta, el proyecto de sentencia se hizo público(6), con la misma anticipación que la publicación de listas de los asuntos.</div>','4','apartado','ANTECEDENTES Y TRÁMITE DE LA DEMANDA','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('0f909d61-f8df-5baa-9182-376d2b5c7c8f','bc88f14b-069f-56d9-b9a9-6456e808561d','I. COMPETENCIA','<div> I. COMPETENCIA<br/> </div>
<div> 13.     Este Tribunal Pleno de la Suprema Corte de Justicia de la Nación es competente para conocer de la presente controversia constitucional, de conformidad con lo dispuesto por los artículos 105, fracción I, inciso a)(7), de la Constitución Política de los Estados Unidos Mexicanos, 1o., de la Ley Reglamentaria de las Fracciones I y II del artículo 105 de esa Norma Fundamental(8), y 16, fracción I, de la Ley Orgánica del Poder Judicial de la Federación(9), así como el Punto Segundo, fracción I, del Acuerdo General 2/2025 (12a.) de tres de septiembre de dos mil veinticinco, del Pleno de la Suprema Corte de Justicia de la Nación, en el que se precisan los asuntos de su competencia y los que se delegan a otros órganos jurisdiccionales federales(10), en virtud de que se plantea un conflicto entre la Federación y una entidad federativa.</div>','5','apartado','I. COMPETENCIA','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('c59f572c-7e76-5b3c-a601-1cf9401a1744','bc88f14b-069f-56d9-b9a9-6456e808561d','II. PRECISIÓN Y EXISTENCIA DEL ACTO IMPUGNADO','<div> II. PRECISIÓN Y EXISTENCIA DEL ACTO IMPUGNADO<br/> </div>
<div> 14.     En términos del artículo 41, fracción I, de la citada Ley Reglamentaria(11), es necesario fijar de manera precisa el o los actos cuya invalidez demanda la parte actora y verificar su certeza. Es aplicable la jurisprudencia P./J. 98/2009(12).</div>
<div> 15.     En ese sentido, de la lectura integral de la demanda se advierte que el Poder actor combate, en concreto, el artículo 34, fracción VII, numerales 1, 2 y 3 de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial local el veintitrés de diciembre de dos mil veinticinco, con lo cual se acredita su existencia.</div>','6','apartado','II. PRECISIÓN Y EXISTENCIA DEL ACTO IMPUGNADO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('7b860918-3c02-5550-a3ca-fbef0a192aaf','bc88f14b-069f-56d9-b9a9-6456e808561d','III. OPORTUNIDAD','<div> III. OPORTUNIDAD<br/> </div>
<div> 16.     El artículo 21, fracción II(13), de la Ley Reglamentaria que rige la materia establece un plazo de treinta días hábiles para promover una controversia constitucional cuando se impugnen normas generales, los cuales serán contados a partir del día siguiente a la fecha de su publicación, o del día siguiente al en que se produzca el primer acto de aplicación.</div>
<div> 17.     En el caso, la norma impugnada se publicó oficialmente el veintitrés de diciembre de dos mil veinticinco, por lo que el plazo legal de treinta días hábiles transcurrió del viernes dos de enero de dos mil veintiséis al lunes dieciséis de febrero de dos mil veintiséis, como se muestra en el siguiente calendario:</div>
<table>               <thead><tr> <th> <div> Domingo<br/> </div> </th> <th> <div> Lunes<br/> </div> </th> <th> <div> Martes<br/> </div> </th> <th> <div> Miércoles<br/> </div> </th> <th> <div> Jueves<br/> </div> </th> <th> <div> Viernes<br/> </div> </th> <th> <div> Sábado<br/> </div> </th> </tr></thead><tbody><tr> <td colspan="7"> <div> Diciembre 2025<br/> </div> </td> </tr><tr> <td> <div> 14<br/> </div> </td> <td> <div> 15<br/> </div> </td> <td> <div> 16<br/> </div> </td> <td> <div> 17<br/> </div> </td> <td> <div> 18<br/> </div> </td> <td> <div> 19<br/> </div> </td> <td> <div> 20<br/> </div> </td> </tr><tr> <td> <div> 21<br/> </div> </td> <td> <div> 22<br/> </div> </td> <td> <div> 23<br/> </div> </td> <td> <div> 24<br/> </div> </td> <td> <div> 25<br/> </div> </td> <td> <div> 26<br/> </div> </td> <td> <div> 27<br/> </div> </td> </tr><tr> <td colspan="7"> <div> Enero 2026<br/> </div> </td> </tr><tr> <td> <div> 28<br/> </div> </td> <td> <div> 29<br/> </div> </td> <td> <div> 30<br/> </div> </td> <td> <div> 31<br/> </div> </td> <td> <div> 1<br/> </div> </td> <td> <div> 2<br/> </div> </td> <td> <div> 3<br/> </div> </td> </tr><tr> <td> <div> 4<br/> </div> </td> <td> <div> 5<br/> </div> </td> <td> <div> 6<br/> </div> </td> <td> <div> 7<br/> </div> </td> <td> <div> 8<br/> </div> </td> <td> <div> 9<br/> </div> </td> <td> <div> 10<br/> </div> </td> </tr><tr> <td> <div> 11<br/> </div> </td> <td> <div> 12<br/> </div> </td> <td> <div> 13<br/> </div> </td> <td> <div> 14<br/> </div> </td> <td> <div> 15<br/> </div> </td> <td> <div> 16<br/> </div> </td> <td> <div> 17<br/> </div> </td> </tr><tr> <td> <div> 18<br/> </div> </td> <td> <div> 19<br/> </div> </td> <td> <div> 20<br/> </div> </td> <td> <div> 21<br/> </div> </td> <td> <div> 22<br/> </div> </td> <td> <div> 23<br/> </div> </td> <td> <div> 24<br/> </div> </td> </tr><tr> <td> <div> 25<br/> </div> </td> <td> <div> 26<br/> </div> </td> <td> <div> 27<br/> </div> </td> <td> <div> 28<br/> </div> </td> <td> <div> 29<br/> </div> </td> <td> <div> 30<br/> </div> </td> <td> <div> 31<br/> </div> </td> </tr><tr> <td colspan="7"> <div> Febrero 2026<br/> </div> </td> </tr><tr> <td> <div> 1<br/> </div> </td> <td> <div> 2<br/> </div> </td> <td> <div> 3<br/> </div> </td> <td> <div> 4<br/> </div> </td> <td> <div> 5<br/> </div> </td> <td> <div> 6<br/> </div> </td> <td> <div> 7<br/> </div> </td> </tr><tr> <td> <div> 8<br/> </div> </td> <td> <div> 9<br/> </div> </td> <td> <div> 10<br/> </div> </td> <td> <div> 11<br/> </div> </td> <td> <div> 12<br/> </div> </td> <td> <div> 13<br/> </div> </td> <td> <div> 14<br/> </div> </td> </tr><tr> <td> <div> 15<br/> </div> </td> <td> <div> 16<br/> </div> </td> <td> <div> 17<br/> </div> </td> <td> <div> 18<br/> </div> </td> <td> <div> 19<br/> </div> </td> <td> <div> 20<br/> </div> </td> <td> <div> 21<br/> </div> </td> </tr></tbody></table>
<div> 18.     De dicho plazo deben descontarse los sábados y domingos, así como los días veinticuatro al treinta y uno de diciembre, todos de dos mil veinticinco, el uno de enero, dos y cinco de febrero de dos mil veintiséis, por ser inhábiles, de conformidad con los artículos 2o. de la Ley Reglamentaria; 3 y 229 de la Ley Orgánica del Poder Judicial de la Federación; el Punto Primero, incisos c) y e), del Acuerdo General 18/2013, de diecinueve de diciembre de dos mil trece, del Pleno de la Suprema Corte de Justicia de la Nación relativo a la determinación de los días hábiles e inhábiles respecto de los asuntos de su competencia, así como de los de descanso para su personal, y 74, fracción II, de la Ley Federal del Trabajo.(14)</div>
<div> 19.     Por lo tanto, si la demanda se presentó el dieciséis de febrero de dos mil veintiséis en la Oficina de Certificación Judicial y Correspondencia de este Alto Tribunal(15), debe concluirse que es oportuna.</div>','7','apartado','III. OPORTUNIDAD','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('db21d6ca-7f59-5166-a1ca-a578f1105ce9','bc88f14b-069f-56d9-b9a9-6456e808561d','IV. LEGITIMACIÓN','<div> IV. LEGITIMACIÓN<br/> </div>
<div> 20.     Del artículo 10, fracciones I, II y III, en relación con el 11, párrafos primero y tercero, de la Ley Reglamentaria(16), se desprende que el actor, demandado y tercero interesado deberán comparecer a juicio por conducto de los funcionarios que, en términos de las normas que lo rigen, estén facultados para representarlos y, en todo caso, se presumirá que quien comparece a juicio goza de la representación legal y cuenta con la capacidad para hacerlo, salvo prueba en contrario.</div>
<div> A.    Legitimación activa.</div>
<div> 21.     La demanda fue suscrita por Esthela Damián Peralta, en su carácter de Consejera Jurídica del Poder Ejecutivo Federal, lo que acredita mediante copia certificada de su nombramiento, expedido el dieciocho de diciembre de dos mil veinticinco(17). Al respecto, debe destacarse que dicho Poder cuenta con legitimación para promover controversias constitucionales en nombre de la Federación, acorde con el criterio de la extinta Segunda Sala contenido en la tesis 2a. XLVII/2003(18), de rubro: "CONTROVERSIA CONSTITUCIONAL. EL TITULAR DEL PODER EJECUTIVO FEDERAL ESTÁ LEGITIMADO PARA PROMOVERLA EN NOMBRE DE LA FEDERACIÓN."; por tanto, cuenta con legitimación procesal activa en este asunto.</div>
<div> B.    Legitimación pasiva.</div>
<div> 22.     El Poder Ejecutivo del Estado de Coahuila de Zaragoza compareció por conducto de Juan Pablo Alvarado Cepeda, en su carácter de Consejero Jurídico del Gobierno del Estado de Coahuila de Zaragoza, lo que acredita mediante copia certificada de su nombramiento expedido el seis de agosto de dos mil veinticinco(19); y en términos del artículo 21, fracción XXX, de la Ley Orgánica de la Administración Pública de dicha entidad federativa(20), en relación con los diversos 5, fracción VII y 25, fracción VIII, del Reglamento Interior de la Secretaría de Gobierno local(21), dicho funcionario representa al Ejecutivo local en las acciones y controversias a que se refiere el artículo 105 de la Constitución Federal; por tanto, cuenta con legitimación pasiva en este asunto.</div>
<div> 23.     Por su parte, el Poder Legislativo del Estado de Coahuila de Zaragoza compareció a través de César Mario Esquivel Flores, en su carácter de Director de Asuntos Jurídicos del Congreso del Estado de Coahuila de Zaragoza y representante legal de dicho órgano legislativo, lo que acredita mediante copias certificadas de su nombramiento de trece de agosto de dos mil veinticinco(22); y del acuerdo de siete de enero de dos mil veintiséis, mediante el cual María del Mar Treviño Garza, en su carácter de Presidenta de la Mesa Directiva del Congreso del Estado, le otorgó poder general para pleitos y cobranzas y actos de administración; lo que encuentra fundamento en el artículo 48, fracción I, de la Ley Orgánica del Congreso de la entidad federativa(23); por tanto, cuenta con legitimación pasiva en este asunto.</div>
<div> C.    Terceros interesados.</div>
<div> 24.     La Cámara de Diputados del Congreso de la Unión compareció por conducto de Kenia López Rabadán, en su carácter de Presidenta de su Mesa Directiva, lo que acredita con el Diario de los Debates de dicha Cámara de dos de septiembre de dos mil veinticinco, en donde consta su nombramiento; y en términos de los artículos 22, numeral 1, y 23, numeral 1, inciso l), de la Ley Orgánica del Congreso General de los Estados Unidos Mexicanos(24), ejerce la representación legal de dicha autoridad legislativa.</div>
<div> 25.     Finalmente, por la Cámara de Senadores del Congreso de la Unión compareció Laura Itzel Castillo Juárez, en su carácter de Presidenta de su Mesa Directiva, lo que acredita con el Acta de la Junta Previa, de veintinueve de agosto de dos mil veinticinco, correspondiente al Primer Periodo Ordinario de Sesiones del Segundo Año de Ejercicio de la Sexagésima Sexta Legislatura del órgano legislativo; y con fundamento en los artículos 62, numeral 1, y 67, numeral 1, inciso l), de la Ley Orgánica del Congreso General de los Estados Unidos Mexicanos(25), ejerce la representación legal de dicha autoridad legislativa.</div>
<div> 26.     En esos términos, al ser dichas Cámaras del Congreso de la Unión parte de la Federación, cuentan con el carácter de terceros interesados en este asunto.</div>','8','apartado','IV. LEGITIMACIÓN','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('de31410d-cc22-5905-802d-965c240df59b','bc88f14b-069f-56d9-b9a9-6456e808561d','V. CAUSAS DE IMPROCEDENCIA Y SOBRESEIMIENTO','<div> V. CAUSAS DE IMPROCEDENCIA Y SOBRESEIMIENTO<br/> </div>
<div> 27.     Si bien no lo alega como causal de improcedencia, el Poder Ejecutivo del Estado de Coahuila de Zaragoza sostiene que su participación en el proceso de creación de la norma combatida se limitó a su promulgación y publicación, en cumplimiento a sus facultades constitucionales, razón por la cual sostiene la validez de tales actuaciones.</div>
<div> 28.     Dicho argumento debe desestimarse, dado que, al tener injerencia en el proceso legislativo de las normas generales impugnadas para otorgarles plena validez y eficacia, se encuentra invariablemente implicado en su emisión, por lo que debe responder por la constitucionalidad de sus actos, siendo aplicable por analogía el criterio contenido en la jurisprudencia P./J. 38/2010(26).</div>
<div> 29.     Al no hacerse valer una diversa causal de improcedencia por las partes, ni advertirse de oficio la actualización de alguna otra, se procede al estudio de fondo.</div>','9','apartado','V. CAUSAS DE IMPROCEDENCIA Y SOBRESEIMIENTO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('dddd1804-5004-5f9a-bc96-a63b5590ba2f','bc88f14b-069f-56d9-b9a9-6456e808561d','VI. ESTUDIO DE FONDO','<div> VI. ESTUDIO DE FONDO<br/> </div>
<div> 30.     En su demanda, el Poder Ejecutivo Federal hace valer los siguientes conceptos de invalidez:</div>
<div> ·   PRIMERO. Se invade la competencia exclusiva de la Federación en materia de hidrocarburos. La norma impugnada invade la esfera competencial de la Federación, al establecer cobros por la expedición de licencias de funcionamiento respecto de edificaciones para la extracción de gas natural y gas no asociado.</div>
<div>        La industria de los hidrocarburos se encuentra sujeta a un régimen constitucional federal especializado, cuya regulación, planeación, autorización, supervisión y vigilancia corresponde a la Federación, en términos de los artículos 25, 27, 28 y 73, fracciones X y XXIX, numerales 2o. y 5o., inciso c), de la Constitución Federal.</div>
<div>        Aunque los Municipios cuentan con facultades en materia de funcionamiento de establecimientos, uso de suelo, desarrollo urbano y licencias de construcción, éstas deben ejercerse conforme a las leyes federales y estatales aplicables, por lo que no pueden utilizarse para condicionar, gravar o interferir en actividades vinculadas con la exploración y extracción de hidrocarburos.</div>
<div>        Al resolver, entre otras, las controversias constitucionales 35/2025, 95/2025, 98/2025, 101/2025, 102/2025, 108/2025, 116/2025, 120/2025, 121/2025 y 131/2025, ese Tribunal Pleno sostuvo que los Municipios no pueden establecer cobros vinculados con licencias de funcionamiento o autorizaciones respecto de establecimientos dedicados a la venta, distribución o expendio de gas LP, al tratarse de una materia reservada a la Federación, por lo que el criterio adoptado en esos precedentes resulta aplicable al presente asunto.</div>
<div> ·   SEGUNDO. Se invade la competencia exclusiva de la Federación en materia de energía eléctrica. La norma impugnada invade la esfera competencial de la Federación, al establecer cobros por la expedición de licencias de funcionamiento respecto de edificaciones productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, por cada aerogenerador o unidad.</div>
<div>        La industria eléctrica constituye un área estratégica cuya planeación, control, regulación, vigilancia y régimen contributivo corresponden exclusivamente a la Federación, en términos de los artículos 25, 27, 28 y 73, fracciones X y XXIX, numeral 5o., inciso a), de la Constitución Federal.</div>
<div>        Aunque los Municipios cuentan con facultades en materia de uso de suelo y licencias de construcción, éstas deben ejercerse conforme a las leyes federales y estatales aplicables, por lo que no pueden utilizarse para condicionar, gravar o interferir en infraestructura necesaria para la generación de energía eléctrica.</div>
<div>        Al resolver las controversias constitucionales 35/2025, 95/2025, 98/2025, 101/2025, 102/2025, 108/2025, 116/2025, 120/2025, 121/2025 y 131/2025, 103/2025, 109/2025, 128/2025, 126/2025, 122/2025, entre otras, el Pleno de ese Alto Tribunal sostuvo que los Municipios no pueden establecer cobros vinculados con infraestructura destinada a la generación, transmisión o distribución de energía eléctrica, al tratarse de una materia reservada a la Federación, por lo que el criterio adoptado en esos precedentes resulta aplicable al presente asunto.</div>
<div> ·   TERCERO. Vulneración al principio de dignidad humana y al acceso a la energía como derecho económico, social, cultural y ambiental. La norma impugnada también vulnera el principio de dignidad humana, al imponer cargas económicas locales sobre actividades vinculadas con la generación de energía eléctrica y la extracción de hidrocarburos, lo que puede obstaculizar el acceso efectivo a la energía en condiciones de disponibilidad, continuidad, accesibilidad y asequibilidad.</div>
<div>        El acceso a la energía constituye un presupuesto para el ejercicio de diversos derechos económicos, sociales, culturales y ambientales, por lo que el Estado debe actuar con debida diligencia para remover obstáculos normativos o económicos que limiten su satisfacción.</div>
<div>        En ese sentido, la norma cuestionada coloca a las personas en una situación de subordinación económica, pues permite que una autoridad municipal imponga cobros indebidos sobre actividades energéticas cuya regulación corresponde a la Federación.</div>
<div> 31.     La norma impugnada dispone lo siguiente:</div>
<table>   <thead><tr> <th> <div> Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza,  para el Ejercicio Fiscal 2026<br/> </div> </th> </tr></thead><tbody><tr> <td> <div> "ARTÍCULO 34.- Con base en la Ley General del Equilibrio Ecológico y la Protección al Ambiente, y la Ley del Equilibrio Ecológico y la Protección al Ambiente del Estado de Coahuila de Zaragoza, son objeto de estos derechos, los servicios prestados por las autoridades municipales por concepto de:</div> <div> [...]</div> <div> VII.- Por la expedición de Licencia de Funcionamiento de las centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, así como de las edificaciones para la extracción del gas natural y gas no asociado, se cobrará anualmente la siguiente tarifa:</div> <div> 1.- Edificación productora de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares, $41,951.83 cada aerogenerador o unidad.</div> <div> 2.- Edificación para la extracción de Gas Natural $41,951.83 cada unidad.</div> <div> 3.- Edificación para la extracción de Gas No Asociado $41,951.83 cada unidad."</div> </td> </tr></tbody></table>
<div> 32.     Visto lo anterior, es esencialmente fundado lo que alega la parte actora.</div>
<div> 33.     Este Tribunal Pleno en diversos precedentes ha declarado la invalidez de normas con una estructura normativa sustancialmente idénticas a la impugnada en este asunto.(27)</div>
<div> 34.     De manera destacada, al resolver las controversias constitucionales 101/2025, 121/2025 y 112/2025(28), en sesión de diecisiete de septiembre de dos mil veinticinco, bajo las ponencias de las Ministras Yasmín Esquivel Mossa y Loretta Ortiz Ahlf, respectivamente, el Tribunal Pleno declaró la invalidez de disposiciones contenidas en las leyes de ingresos de los Municipios de San Juan de Sabinas, Ocampo e Hidalgo, todos del Estado de Coahuila de Zaragoza, para el Ejercicio Fiscal 2025, en las que, como en el caso que nos ocupa, se establecían cobros por la expedición de licencias de funcionamiento respecto de centrales productoras de energía y edificaciones destinadas a la extracción de gas natural y gas no asociado, al considerar que dichas previsiones inciden en materias reservadas de manera exclusiva a la Federación.</div>
<div> 35.     Criterio similar fue reiterado por la actual integración de este Tribunal Pleno al resolver las controversias constitucionales 101/2025, 110/2025, 119/2025, 121/2025, 128/2025, 102/2025, 116/2025, 108/2025, 114/2025, 123/2025, 98/2025,107/2025 y 131/2025(29), en sesiones de diecisiete y dieciocho de septiembre, veintisiete y veintiocho de octubre, cuatro y once de noviembre, y ocho de diciembre de dos mil veinticinco, en las se impugnaron artículos contenidos en leyes de ingresos de diversos Municipios del Estado de Coahuila, para el Ejercicio Fiscal 2025.</div>
<div> 36.     Para fines ejemplificativos, la estructura normativa del precepto que fue analizado en la controversia constitucional 112/2025, se muestra frente al que se combate en este asunto:</div>
<table>   <thead><tr> <th> <div> Norma impugnada en la controversia constitucional 112/2025<br/> </div> </th> <th> <div> Norma impugnada en esta controversia constitucional 120/2026<br/> </div> </th> </tr></thead><tbody><tr> <td> <div> "ARTÍCULO 20.- Con base en la Ley General de Equilibrio Ecológico y la Protección al Ambiente, y la Ley del Equilibrio Ecológico y la Protección al Ambiente del Estado de Coahuila de Zaragoza, son objeto de estos derechos, los servicios prestados por las autoridades municipales por concepto de:</div> <div> I.- Por la expedición de Licencia de Funcionamiento de las centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, así como de las edificaciones para la extracción del gas de lutitas o gas shale, gas natural y gas no asociado y los pozos para la extracción de cualquier hidrocarburo, se cobrará anualmente la siguiente tarifa:</div> <div> 1.- Edificación para la extracción de gas de lutitas o gas shale $39,477.00 por cada unidad.</div> <div> 2.- Edificación productora de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares, $39,477.00 por cada aerogenerador o unidad.</div> <div> 3.- Edificación para la extracción de Gas Natural $39,477.00 por cada unidad.</div> <div> 4.- Edificación para la extracción de Gas No Asociado $39,477.00 por cada unidad.</div> <div> 5.- Por perforación de pozos verticales y direccionales en el área específica a yacimientos convencionales (Roca Reservorio) en trampas estructurales en el que se encuentre el hidrocarburo $39,477.00 por cada pozo.</div> <div> 6.- Por perforación de pozo para la extracción de cualquier hidrocarburo $39,477.00 por cada pozo."</div> </td> <td> <div> "ARTÍCULO 34.- Con base en la Ley General del Equilibrio Ecológico y la Protección al Ambiente, y la Ley del Equilibrio Ecológico y la Protección al Ambiente del Estado de Coahuila de Zaragoza, son objeto de estos derechos, los servicios prestados por las autoridades municipales por concepto de:</div> <div> [...]</div> <div> VII.- Por la expedición de Licencia de Funcionamiento de las centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, así como de las edificaciones para la extracción del gas natural y gas no asociado, se cobrará anualmente la siguiente tarifa:</div> <div> 1.- Edificación productora de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares, $41,951.83 cada aerogenerador o unidad.</div> <div> 2.- Edificación para la extracción de Gas Natural $41,951.83 cada unidad.</div> <div> 3.- Edificación para la extracción de Gas No Asociado $41,951.83 cada unidad."</div> </td> </tr></tbody></table>
<div> 37.     Como se advierte, las disposiciones comparadas comparten la misma estructura normativa relevante, pues ambas establecen un cobro anual por la expedición de licencias de funcionamiento respecto de la edificación de centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares, así como edificaciones destinadas a la extracción de gas natural y gas no asociado, siendo que la diferencia entre ambos preceptos se reduce, esencialmente, al monto de las tarifas y a que la norma analizada en la controversia constitucional 112/2025 incluía otros supuestos adicionales -como la extracción de gas de lutitas o gas shale y la perforación de pozos-, sin que ello desvirtúe la identidad sustancial de los conceptos ahora controvertidos.</div>
<div> 38.     Atento a ello, se retoman las consideraciones que fueron desarrolladas en aquellos precedentes, en lo que respecta al parámetro constitucional que rige la competencia de la Federación tanto en materia de hidrocarburos, como en materia de energía eléctrica; posteriormente, se analizará el alcance de las facultades municipales en materia hacendaria, administrativa y de licencias de funcionamiento, y, finalmente, se analizará el caso concreto, lo que se realiza a continuación:</div>','10','apartado','VI. ESTUDIO DE FONDO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('41abfb29-90a7-58c3-bd5a-725d560590d1','bc88f14b-069f-56d9-b9a9-6456e808561d','VI.1 Parámetro constitucional aplicable en materia de hidrocarburos','<div> VI.1 Parámetro constitucional aplicable en materia de hidrocarburos<br/> </div>
<div> 39.     El artículo 25, primer párrafo(30), de la Constitución Política de los Estados Unidos Mexicanos señala que corresponde al Estado la rectoría del desarrollo nacional para garantizar que éste sea integral y sustentable.</div>
<div> 40.     Con miras a ello, el párrafo quinto(31) de dicho numeral establece que el sector público tendrá a su cargo, de manera exclusiva, las áreas estratégicas que se señalan en el diverso 28, párrafo cuarto, de la Constitución Federal, manteniendo siempre el Gobierno Federal la propiedad y el control sobre los organismos y empresas productivas del Estado que en su caso se establezcan. Asimismo, precisa que tratándose de la planeación y el control de la exploración y extracción del petróleo y demás hidrocarburos, la Nación llevará dichas actividades en términos de lo dispuesto en los párrafos sexto y séptimo del artículo 27 de la Norma Fundamental.</div>
<div> 41.     Además, conforme al artículo 27, párrafo cuarto(32), de la Constitución Federal corresponde a la Nación el dominio directo de todos los recursos naturales, tales como los combustibles, minerales sólidos, el petróleo y de todos los carburos de hidrógeno sólidos, líquidos o gaseosos.</div>
<div> 42.     Por su parte, el párrafo sexto(33) del referido artículo 27 constitucional prevé que, respecto de estos recursos, el dominio de la Nación es inalienable e imprescriptible y la explotación, así como el uso o aprovechamiento de los recursos de que se trata, por los particulares o por sociedades constituidas conforme a las leyes mexicanas, no podrá realizarse sino mediante concesiones otorgadas por el Ejecutivo Federal, de acuerdo con las reglas y condiciones que establezcan las leyes.</div>
<div> 43.     A su vez, el artículo 28, párrafo cuarto(34), de la Constitución Federal contempla que no constituyen monopolios las funciones que el Estado ejerza de manera exclusiva en áreas estratégicas tales como la exploración y extracción del petróleo y de los demás hidrocarburos. El párrafo noveno(35) del mismo precepto pone de manifiesto que el Poder Ejecutivo Federal, por conducto de la dependencia encargada de conducir y supervisar la política energética del país, contará con las atribuciones para llevar a cabo la regulación técnica y económica; así como la facultad sancionadora en materia energética y de hidrocarburos, en los términos que determine la ley.</div>
<div> 44.     En relación con la facultad de legislar en materia de hidrocarburos, el artículo 73, fracción X(36), de la Constitución Federal señala que el Congreso de la Unión tiene facultad para legislar  en toda la República, entre otros ámbitos, sobre hidrocarburos. Además, la fracción XXIX,  numeral 2(37) del mismo precepto constitucional prevé que el Congreso de la Unión tiene la facultad para establecer contribuciones sobre el aprovechamiento y explotación de recursos naturales comprendidos en los artículos 4, 5 y 27, como son los hidrocarburos. Asimismo, el numeral 5o., inciso c), de la propia fracción XXIX(38), faculta al Congreso de la Unión para establecer contribuciones especiales sobre gasolina y otros productos derivados del petróleo.</div>
<div> 45.     Del análisis integral de los referidos preceptos constitucionales se advierte que los recursos naturales, tales como los hidrocarburos, resultan bienes del dominio de la Nación. Para realizar la explotación de dicho recurso, se encomienda al Estado su rectoría económica, para lo cual, en términos de la propia Constitución Federal, se prevé que el Gobierno Federal mantendrá la propiedad y el control sobre los organismos y empresas productivas del Estado que en su caso se establezcan.</div>
<div> 46.     Conforme a lo anterior, se concluye que en todo momento el Estado mantiene el dominio originario, inalienable e imprescriptible sobre la exploración y extracción de hidrocarburos. Por su parte, si bien las normas constitucionales dejan entrever que existe la posibilidad de otorgar autorizaciones para que particulares o sociedades constituidas realicen el uso o aprovechamiento de ciertos recursos naturales, como los hidrocarburos, dicha actividad se llevará a cabo bajo la supervisión del Estado.</div>
<div> 47.     Para ejercer esa vigilancia, las normas constitucionales señalan que el Estado contará con las atribuciones para llevar a cabo la regulación técnica y económica; así como la facultad sancionadora en materia energética y de hidrocarburos; lo que realizará por conducto de la Comisión Nacional de Energía(39), como órgano de carácter técnico, sectorizado a la Secretaría de Energía(40), que tiene por objeto regular, supervisar e imponer sanciones en las actividades de la materia energética.</div>
<div> 48.     Ahora, en el marco normativo vigente, los artículos 1 y 6 de la Ley del Sector Hidrocarburos establecen que corresponde a la Nación la propiedad directa, inalienable e imprescriptible de todos los hidrocarburos que se encuentran en el subsuelo del territorio nacional; además, que las actividades de exploración y extracción de hidrocarburos las llevará a cabo, únicamente, la Nación a través de asignatarias o contratistas, en los términos que establezca dicha ley.(41)</div>
<div> 49.     De igual manera, los artículos 8 y 9 de la Ley del Sector Hidrocarburos(42), disponen que corresponde a la Secretaría de Energía determinar los proyectos estratégicos de infraestructura, necesarios para cumplir con la política energética nacional e impulsar su ejecución, para lo cual dicha Secretaría y la Comisión Nacional de Energía deben ejercer sus facultades de emisión de regulación y de otorgamiento de autorizaciones, aprobaciones y permisos (que exige dicha Ley) para almacenar, transportar y distribuir por ductos el petróleo, gas, petrolíferos y petroquímicos, así como para la comercialización, y expendio al público de gas natural.</div>
<div> 50.     En ese orden de ideas, en los artículos 76, fracción II y 116, fracciones I y III de la Ley del Sector Hidrocarburos(43), así como el diverso 9, fracción II(44), de la Ley de la Comisión Nacional de Energía, facultan a esta Comisión para regular y otorgar los permisos para el transporte y almacenamiento de hidrocarburos y petrolíferos; el transporte por ductos y el almacenamiento de petroquímicos vinculados a ductos; la distribución de gas natural y petrolíferos; la comercialización y expendio al público de gas y petrolíferos, y para supervisar las actividades reguladas a fin de evaluar su funcionamiento conforme a la política energética que se haya definido.</div>
<div> 51.     Asimismo, la regulación técnica federal en materia de gas confirma que la distribución, transporte, suministro y aprovechamiento de gas no constituyen simples actividades comerciales ordinarias, sino actividades sujetas a estándares especializados de seguridad industrial, seguridad operativa y protección ambiental, como se muestra a continuación:</div>
<div> ·   La Secretaría de Energía emitió la Norma Oficial Mexicana NOM-004-SEDG-2004, "Instalaciones de aprovechamiento de Gas L.P. Diseño y construcción", publicada en el Diario Oficial de la Federación el dos de diciembre de dos mil cuatro, cuyo objeto consiste en establecer las especificaciones técnicas mínimas de seguridad aplicables al diseño, construcción y modificación de instalaciones fijas y permanentes destinadas al aprovechamiento de gas licuado de petróleo, así como los procedimientos para la evaluación de su conformidad.</div>
<div> ·   La Comisión Reguladora de Energía emitió la Norma Oficial Mexicana NOM-002-SECRE-2010, "Instalaciones de aprovechamiento de gas natural", publicada en el Diario Oficial de la Federación el cuatro de febrero de dos mil once, cuyo objeto consiste en establecer los requisitos mínimos de seguridad aplicables al diseño, materiales, construcción, instalación, pruebas de hermeticidad, operación, mantenimiento y seguridad de las instalaciones destinadas al aprovechamiento de gas natural, desde la salida del medidor o de una estación de regulación y medición hasta los aparatos de consumo.</div>
<div> ·   La Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos emitió la Norma Oficial Mexicana NOM-020-ASEA-2024, "Transporte de gas natural por medio de ductos terrestres", publicada en el Diario Oficial de la  Federación el primero de septiembre de dos mil veinticinco, la cual cancela y sustituye  a la NOM-007-ASEA-2016. Dicha norma regula las especificaciones y requisitos de seguridad industrial, seguridad operativa y protección ambiental aplicables a los sistemas de transporte de gas natural por ductos terrestres.</div>
<div> ·   La Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos emitió la Norma Oficial Mexicana NOM-003-ASEA-2016, "Distribución de gas natural y gas licuado de petróleo por ductos", publicada en el Diario Oficial de la  Federación el dieciocho de agosto de dos mil diecisiete, la cual cancela y sustituye a la  NOM-003-SECRE-2011. Dicha norma establece los requisitos técnicos y de seguridad aplicables al diseño, construcción, pre-arranque, operación, mantenimiento, cierre y desmantelamiento de los sistemas de distribución de gas natural y gas licuado de petróleo por ductos.</div>
<div> ·   La Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos emitió la Norma Oficial Mexicana NOM-018-ASEA-2023, "Plantas de Distribución de Gas Licuado de Petróleo", publicada en el Diario Oficial de la Federación el cinco de diciembre de dos mil veintitrés, cuyo objeto consiste en establecer los requisitos y especificaciones de seguridad industrial, seguridad operativa y protección al medio ambiente que deben cumplir las plantas de distribución de Gas L.P. durante las etapas de diseño, construcción, operación y mantenimiento. Dicha norma cancela y sustituye a la NOM-001-SESH-2014.</div>
<div> ·   Finalmente, la Agencia Nacional de Seguridad Industrial y de Protección al Medio  Ambiente del Sector Hidrocarburos emitió la Norma Oficial Mexicana de Emergencia  NOM-EM-006-ASEA-2025, "Transporte de Gas Licuado de Petróleo", publicada en el Diario Oficial de la Federación el tres de octubre de dos mil veinticinco, cuyo objeto consiste en establecer las especificaciones técnicas y requisitos de seguridad industrial, seguridad operativa y protección al medio ambiente que deben cumplir quienes realicen el transporte de Gas L.P. por medio de auto-tanque y semirremolque con tractocamión.</div>
<div> 52.     La existencia de este entramado normativo técnico evidencia que las actividades relacionadas con el transporte, distribución, almacenamiento, suministro, expendio y aprovechamiento de gas se encuentran sujetas a una regulación federal especializada, uniforme y de alcance nacional, cuya supervisión y verificación corresponde a autoridades federales competentes.</div>
<div> 53.     Atento a lo expuesto, el régimen constitucional y legal aplicable permite concluir que las decisiones normativas, técnicas y administrativas sobre la planeación, regulación, autorización, supervisión y verificación de las actividades que integran la industria de los hidrocarburos corresponden a las autoridades federales competentes. Ello comprende, entre otras, las actividades de transporte, almacenamiento, distribución, comercialización y expendio al público de gas y petrolíferos, así como la infraestructura, instalaciones y condiciones técnicas necesarias para su desarrollo, pues dichos elementos forman parte del funcionamiento integral del sector hidrocarburos.</div>','11','apartado','VI.1 Parámetro constitucional aplicable en materia de hidrocarburos','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('cb5f99c3-0beb-5234-b5dc-2ddf771d007a','bc88f14b-069f-56d9-b9a9-6456e808561d','VI.2 Parámetro constitucional aplicable en materia de energía eléctrica','<div> VI.2 Parámetro constitucional aplicable en materia de energía eléctrica<br/> </div>
<div> 54.     De acuerdo con el párrafo quinto del artículo 25 de la Constitución Federal, la materia de energía eléctrica es un área exclusiva del Estado, específicamente, tratándose de la planeación y control del sistema eléctrico nacional y del servicio público de trasmisión y distribución de energía eléctrica. También se precisa que, tratándose de la planeación y control del sistema eléctrico nacional y del servicio público respectivo, la Nación llevará dichas actividades en términos de lo dispuesto en los párrafos sexto y séptimo del artículo 27 de la Norma Fundamental.(45)</div>
<div> 55.     A su vez, el artículo 28, párrafo cuarto, de la Constitución Federal contempla que no constituyen monopolios las funciones que el Estado ejerza de manera exclusiva en áreas estratégicas tales como la planeación y el control del sistema eléctrico nacional, cuyos objetivos serán preservar la seguridad y autosuficiencia energética de la Nación y proveer al pueblo de la electricidad al menor precio posible, evitando el lucro, para garantizar la seguridad nacional y soberanía a través de la empresa pública del Estado que se establezca; así como el servicio público de transmisión y distribución de energía eléctrica.(46)</div>
<div> 56.     Asimismo, el párrafo noveno de la misma disposición constitucional prevé que el Poder Ejecutivo Federal, por conducto de la dependencia encargada de conducir y supervisar la política energética del país, contará con las atribuciones para llevar a cabo la regulación técnica y económica; así como la facultad sancionadora en materia energética y de hidrocarburos, en los términos que determine la ley.(47)</div>
<div> 57.     En relación con la facultad de legislar en materia de energía eléctrica, el artículo 73, fracción X, de la Constitución Federal señala que el Congreso de la Unión tiene facultad para legislar en toda la República, entre otros ámbitos, sobre energía eléctrica. Además, en la fracción XXIX, numeral 5o., inciso a), del mismo precepto se establece que el Congreso de la Unión tiene la facultad para establecer contribuciones sobre esta materia.(48)</div>
<div> 58.     Del análisis integral de los referidos preceptos constitucionales se advierte que el Estado tendrá a su cargo, exclusivamente, la planeación y control del sistema eléctrico nacional y del servicio público de transmisión y distribución de energía eléctrica cuyos objetivos serán preservar la seguridad y autosuficiencia energética de la Nación y proveer al pueblo de la electricidad al menor precio posible, evitando el lucro, para garantizar la seguridad nacional.</div>
<div> 59.     En cuanto al marco regulatorio en materia energética, el dieciocho de marzo de dos mil veinticinco se publicó en el Diario Oficial de la Federación la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, que entró en vigor al día siguiente de su publicación. Este ordenamiento asigna de manera directa a la referida Comisión las actividades de transmisión, distribución y suministro básico de este servicio, las cuales no constituyen un monopolio.(49)</div>
<div> 60.     En esa misma fecha también se expidió la Ley del Sector Eléctrico, la cual tiene por objeto regular la planeación y el control del Sistema Eléctrico Nacional, el Servicio Público de Transmisión y Distribución de Energía Eléctrica, así como las demás actividades del sector eléctrico.(50)</div>
<div> 61.     Asimismo, dicha Ley precisa que el sector eléctrico comprende las actividades de generación, almacenamiento, transmisión, distribución y comercialización de la energía eléctrica, así como, la planeación y el control del Sistema Eléctrico Nacional, la operación del Mercado Eléctrico Mayorista, y la proveeduría de insumos primarios para el sector eléctrico, las cuales son de interés público, cuya planeación y control son áreas estratégicas del Estado.(51)</div>
<div> 62.     En cuanto a las actividades de generación, transmisión y distribución de la energía eléctrica, establece que el Sistema Eléctrico Nacional es un servicio de interés público cuya infraestructura física permite la transmisión, distribución y control del sistema eléctrico; la cual se integra por la red nacional de transmisión, redes generales de distribución, centrales eléctricas que entreguen energía a la red nacional de transmisión o redes generales de distribución y equipos o instalaciones del Centro Nacional de Control de Energía para llevar a cabo el control operativo del sistema eléctrico nacional.(52)</div>
<div> 63.     Las actividades de planeación y control de la infraestructura eléctrica se llevan a cabo mediante el Programa de Desarrollo del Sistema Eléctrico Nacional, emitido por la Secretaría de Energía que, entre otras cuestiones, incluye programas indicativos para la instalación y retiro de las Centrales Eléctricas, para la ampliación y modernización de la Red Nacional de Transmisión y Redes Generales de Distribución; así como para los programas de ampliación y modernización de la Red Nacional de Transmisión y de las Redes Generales de Distribución.</div>
<div> 64.     Finalmente, la Ley de la Comisión Nacional de Energía establece en su artículo 8, fracción IV, que, en el sector eléctrico, la Comisión tiene entre sus atribuciones otorgar, modificar, terminar y supervisar los permisos de generación y comercialización de energía eléctrica, así como emitir las autorizaciones y actos administrativos vinculados al sector, que se requieran.(53)</div>
<div> 65.     Atento a lo expuesto, el régimen constitucional y legal aplicable permite concluir que las decisiones normativas, técnicas y administrativas sobre la planeación, control, regulación y supervisión del Sistema Eléctrico Nacional, así como sobre la generación, transmisión, distribución y comercialización de energía eléctrica, corresponden a las autoridades federales. Ello incluye no sólo la prestación del servicio público de transmisión y distribución, sino también la infraestructura material necesaria para la generación, conducción, transformación, operación, mantenimiento y control de la energía eléctrica, pues dichos elementos constituyen presupuestos indispensables para el funcionamiento del sector eléctrico.</div>','12','apartado','VI.2 Parámetro constitucional aplicable en materia de energía eléctrica','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('0e4337bf-4269-5dc9-8f48-1560efbd2d10','bc88f14b-069f-56d9-b9a9-6456e808561d','VI.3 Alcance de las facultades municipales en materia hacendaria, administrativa y de licencias de funcionamiento','<div> VI.3 Alcance de las facultades municipales en materia hacendaria, administrativa y de licencias de<br/> funcionamiento<br/> </div>
<div> 66.     El artículo 115, fracción IV, de la Constitución Federal establece que los Municipios administrarán libremente su hacienda, la cual se formará de los rendimientos de los bienes que les pertenezcan, así como de las contribuciones y otros ingresos que las legislaturas establezcan a su favor y en todo caso:</div>
<div> a.     Percibirán las contribuciones, incluyendo tasas adicionales, que establezcan los Estados sobre la propiedad inmobiliaria, de su fraccionamiento, división, consolidación, traslación y mejora, así como las que tengan por base el cambio de valor de los inmuebles.</div>
<div>        Los Municipios podrán celebrar convenios con el Estado para que éste se haga cargo de algunas de las funciones relacionadas con la administración de esas contribuciones.</div>
<div> b.     Las participaciones federales, que serán cubiertas por la Federación a los Municipios con arreglo a las bases, montos y plazos que anualmente se determinen por las Legislaturas de los Estados.</div>
<div> c.     Los ingresos derivados de la prestación de servicios públicos a su cargo.</div>
<div> 67.     Asimismo, dispone que los Ayuntamientos, en el ámbito de su competencia, propondrán a las legislaturas estatales las cuotas y tarifas aplicables a impuestos, derechos, contribuciones de mejoras y las tablas de valores unitarios de suelo y construcciones que sirvan de base para el cobro de las contribuciones sobre la propiedad inmobiliaria.</div>
<div> 68.     En ese sentido, la fracción V del citado artículo 115 constitucional señala que los municipios, en los términos de las leyes federales y estatales relativas, estarán facultados para:</div>
<div> a.     Formular, aprobar y administrar la zonificación y planes de desarrollo urbano municipal, así como los planes en materia de movilidad y seguridad vial.</div>
<div> b.     Participar en la creación y administración de sus reservas territoriales.</div>
<div> c.     Participar en la formulación de planes de desarrollo regional, los cuales deberán estar en concordancia con los planes generales de la materia. Cuando la Federación o los Estados elaboran proyectos de desarrollo regional deberán asegurar la participación de los Municipios.</div>
<div> d.     Autorizar, controlar y vigilar la utilización del suelo, en el ámbito de su competencia, en sus jurisdicciones territoriales.</div>
<div> e.     Intervenir en la regularización de la tenencia de la tierra urbana.</div>
<div> f.     Otorgar licencias y permisos para construcciones.</div>
<div> g.     Participar en la creación y administración de zonas de reservas ecológicas y en la elaboración y aplicación de programas de ordenamiento en esta materia.</div>
<div> h.     Intervenir en la formulación y aplicación de programas de transporte público de pasajeros cuando aquellos afecten su ámbito territorial.</div>
<div> i.      Celebrar convenios para la administración y custodia de las zonas federales.</div>
<div> 69.     Además, de acuerdo con el último párrafo de la fracción V del artículo 115 de la Constitución Federal, en lo conducente y de conformidad a los fines señalados en el párrafo tercero del artículo 27 constitucional, los Municipios expedirán los reglamentos y disposiciones administrativas que fueren necesarios. De igual forma, los bienes inmuebles de la Federación ubicados en los municipios estarán exclusivamente bajo la jurisdicción de los poderes federales, sin perjuicio de los convenios que puedan celebrar en términos del inciso i), antes transcrito.</div>
<div> 70.     En vista de lo anterior, este Tribunal Pleno reconoce que los Municipios cuentan con atribuciones constitucionales en materia de desarrollo urbano, uso de suelo, construcciones, administración de la vía pública, protección civil e imagen urbana, en términos del artículo 115 constitucional.</div>
<div> 71.     Sin embargo, dichas facultades no son absolutas ni pueden ejercerse de manera aislada del sistema constitucional de distribución de competencias, pues el propio artículo 115 constitucional establece que los Municipios ejercerán sus atribuciones en los términos de las leyes federales y estatales relativas, por lo que sus competencias deben armonizarse con aquellas materias que la Constitución Federal reserva expresamente a la Federación.</div>
<div> 72.     Por tanto, la potestad municipal para administrar su hacienda, expedir licencias de funcionamiento, regular construcciones, ejercer funciones de control ambiental o cobrar derechos por servicios administrativos locales no puede convertirse en una habilitación para condicionar, regular o gravar de manera específica actividades o infraestructura vinculadas con sectores reservados al ámbito federal, como la exploración y extracción de hidrocarburos o la generación de energía eléctrica.</div>
<div> 73.     Lo anterior no implica desconocer la competencia municipal para regular, en términos generales, el uso de suelo, las construcciones, el funcionamiento de establecimientos o determinados aspectos ambientales dentro de su territorio. Significa, más bien, que cuando la norma local o municipal identifica expresamente actividades o infraestructura propias de la industria de hidrocarburos o del sector eléctrico y establece respecto de ellas un régimen específico de licencia, autorización, permiso o cobro, deja de operar como una regulación administrativa general y pasa a incidir directamente en materias federales.</div>
<div> 74.     En esa medida, debe distinguirse entre una licencia de funcionamiento ordinaria, aplicable de manera general a establecimientos, obras o actividades dentro del territorio municipal, y una autorización o derecho diseñado específicamente para edificaciones destinadas a la extracción de gas natural o gas no asociado, o para edificaciones productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares. La primera puede ubicarse, en principio, dentro del ámbito municipal; la segunda incide en actividades cuya regulación, autorización, supervisión y verificación corresponde a las autoridades federales competentes.</div>
<div> 75.     Esta distinción es relevante porque permitir que cada Municipio establezca licencias, refrendos, permisos o derechos específicos para edificaciones destinadas a la extracción de hidrocarburos o a la producción de energía eléctrica generaría una fragmentación regulatoria incompatible con el diseño constitucional de ambos sectores. Tanto la industria de hidrocarburos como el sector eléctrico requieren criterios técnicos uniformes, planeación nacional, seguridad energética, continuidad, confiabilidad, supervisión especializada y control federal.</div>
<div> 76.     Si bien la legislación federal en materia de hidrocarburos y energía eléctrica prevé mecanismos de coordinación entre la Federación, las entidades federativas y los Municipios para contribuir al desarrollo de determinadas actividades y proyectos, dicha participación debe entenderse limitada al ámbito de competencia de cada orden de gobierno y orientada a agilizar los permisos y autorizaciones que correspondan. Por tanto, esa coordinación no constituye una habilitación para que los Municipios establezcan regímenes autónomos de autorización, licencia, permiso, refrendo o cobro específicamente dirigidos a actividades de exploración o extracción de hidrocarburos, ni a infraestructura del sector eléctrico, máxime que la propia legislación federal reserva dichas materias a la jurisdicción federal.</div>
<div> 77.     En efecto, el artículo 127 de la Ley del Sector Hidrocarburos dispone expresamente que la industria de hidrocarburos es de exclusiva jurisdicción federal y que, en consecuencia, únicamente el Gobierno Federal puede dictar las disposiciones técnicas, reglamentarias y de regulación en la materia, incluyendo aquéllas relacionadas con el desarrollo sustentable, el equilibrio ecológico y la protección al medio ambiente en el desarrollo de esta industria.(54)</div>
<div> 78.     Asimismo, el artículo 78 de la misma Ley prevé que la Secretaría de Energía o la Comisión Nacional de Energía pueden coordinarse con Petróleos Mexicanos o cualquier autoridad del Gobierno Federal, así como celebrar convenios de colaboración y coordinación con autoridades de los tres órdenes de gobierno para que, en el ámbito de su competencia, supervisen, vigilen y verifiquen que las actividades reguladas en dicha Ley se realicen sin perjuicio del interés público y social.(55)</div>
<div> 79.     De igual forma, el artículo 128, párrafo tercero, de dicho ordenamiento establece que la Federación, los gobiernos de los Estados y de la Ciudad de México, los Municipios y las Alcaldías deben contribuir al desarrollo de proyectos de exploración y extracción, así como de transporte y distribución por ductos y de almacenamiento, mediante procedimientos y bases de coordinación que agilicen y garanticen el otorgamiento de los permisos y autorizaciones en el ámbito de su competencia.(56)</div>
<div> 80.     Por su parte, el artículo 7 de la Ley del Sector Eléctrico dispone expresamente que las actividades del sector eléctrico son de jurisdicción federal y que, en los casos en que exista concurrencia, prevalece dicha jurisdicción. Además, establece que las autoridades administrativas y jurisdiccionales deben proveer lo necesario para que no se interrumpan dichas actividades.(57)</div>
<div> 81.     Asimismo, el artículo 88, tercer párrafo, de la misma Ley prevé que la Federación, los gobiernos de las entidades federativas, los Municipios y las alcaldías de la Ciudad de México deben contribuir al desarrollo de proyectos de generación, transmisión y distribución de energía eléctrica, mediante procedimientos y bases de coordinación que agilicen y garanticen el otorgamiento de los permisos y autorizaciones en el ámbito de su competencia.(58)</div>
<div> 82.     De igual forma, el artículo 129 de dicho ordenamiento establece que el Gobierno Federal debe promover el acceso energético, priorizando la electrificación de comunidades rurales y zonas urbanas marginadas, para lo cual la Secretaría de Energía puede coordinarse con las entidades federativas y los Municipios.(59)</div>
<div> 83.     De esas disposiciones se advierte que la legislación federal prevé espacios de coordinación con las entidades federativas y los Municipios en materia de hidrocarburos y energía eléctrica; sin embargo, dicha participación se encuentra acotada al ámbito de competencia de cada orden de gobierno y tiene como finalidad facilitar el desarrollo de proyectos, agilizar trámites y, en su caso, auxiliar en la supervisión, vigilancia y verificación de las actividades reguladas o promover el acceso energético, sin habilitar expresamente a las autoridades locales para establecer regímenes autónomos de autorización, licencia, permiso, refrendo o cobro específicamente dirigidos a actividades de la industria de hidrocarburos o a infraestructura del sector eléctrico.</div>
<div> 84.     En otras palabras, la coordinación prevista en la legislación federal tiene por objeto agilizar y garantizar los permisos y autorizaciones que correspondan a cada orden de gobierno, así como permitir la colaboración institucional para la supervisión, vigilancia y desarrollo de las actividades reguladas, sin trasladar a los órdenes de gobierno estatales y municipales facultades para regular, condicionar o gravar actividades propias de la industria de hidrocarburos o del sector eléctrico.</div>
<div> 85.     Por tanto, si bien subsisten las autorizaciones municipales ordinarias en materia urbanística, administrativa, ambiental o de funcionamiento, éstas no pueden configurarse de manera que el hecho imponible recaiga específicamente sobre actividades de exploración o extracción de hidrocarburos, ni sobre proyectos o infraestructura destinados a la generación, transmisión o distribución de energía eléctrica, ni calcularse con base en elementos propios de dichas actividades reguladas por la legislación federal.</div>
<div> 86.     Lo anterior, porque la legislación federal concentra en autoridades federales el régimen de permisos, autorizaciones, regulación técnica y económica, supervisión, verificación, imposición de sanciones y demás actos administrativos necesarios para el funcionamiento eficiente tanto de la industria de hidrocarburos como del sector eléctrico, por lo que esos elementos no pueden quedar sujetos a regímenes municipales diferenciados.</div>
<div> 87.     En suma, la previsión de facultades municipales en materia hacendaria, administrativa, ambiental, de uso de suelo o licencias de funcionamiento no autoriza a los Municipios a establecer cargas económicas específicas sobre edificaciones destinadas a la extracción de gas natural o gas no asociado, ni sobre edificaciones productoras de energía eléctrica. Admitir lo contrario desnaturalizaría el diseño federal de ambos sectores y permitiría fragmentar localmente materias que la Constitución Federal y las leyes reservan a la jurisdicción federal.</div>','13','apartado','VI.3 Alcance de las facultades municipales en materia hacendaria, administrativa y de licencias de funcionamiento','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('9ba51d78-721b-5e38-9017-b0b45b258c06','bc88f14b-069f-56d9-b9a9-6456e808561d','VI.4 Análisis del caso concreto','<div> VI.4 Análisis del caso concreto<br/> </div>
<div> 88.     En el caso, la norma impugnada, artículo 34, fracción VII, numerales 1, 2 y 3 de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, establece cobros anuales por la expedición de licencia de funcionamiento respecto de edificaciones productoras de energía eléctrica, así como de edificaciones destinadas a la extracción de gas natural y gas no asociado. Vale la pena tener en cuenta su texto íntegro.</div>
<table>   <thead><tr> <th> <div> Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza,  para el Ejercicio Fiscal 2026<br/> </div> </th> </tr></thead><tbody><tr> <td> <div> "ARTÍCULO 34.- Con base en la Ley General del Equilibrio Ecológico y la Protección al Ambiente, y la Ley del Equilibrio Ecológico y la Protección al Ambiente del Estado de Coahuila de Zaragoza, son objeto de estos derechos, los servicios prestados por las autoridades municipales por concepto de:</div> <div> [...]</div> <div> VII.- Por la expedición de Licencia de Funcionamiento de las centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, así como de las edificaciones para la extracción del gas natural y gas no asociado, se cobrará anualmente la siguiente tarifa:</div> <div> 1.- Edificación productora de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares, $41,951.83 cada aerogenerador o unidad.</div> <div> 2.- Edificación para la extracción de Gas Natural $41,951.83 cada unidad.</div> <div> 3.- Edificación para la extracción de Gas No Asociado $41,951.83 cada unidad."</div> </td> </tr></tbody></table>
<div> 89.     Atento a ello, el análisis se dividirá en dos apartados: primero, se estudiará el numeral 1, relativo a edificaciones productoras de energía eléctrica; y, posteriormente, los numerales 2 y 3, relativos a edificaciones destinadas a la extracción de gas natural y gas no asociado.</div>','14','apartado','VI.4 Análisis del caso concreto','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('b285e491-9de7-5799-848f-807d230a7274','bc88f14b-069f-56d9-b9a9-6456e808561d','Numeral 1: Edificaciones productoras de energía eléctrica','<div> Numeral 1: Edificaciones productoras de energía eléctrica<br/> </div>
<div> 90.     El numeral 1 de la fracción VII del artículo 34 impugnado establece un cobro anual por cada aerogenerador o unidad, por concepto de edificación productora de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogenerador o similares.</div>
<div> 91.     Dicho supuesto normativo no constituye un cobro ordinario por el funcionamiento de cualquier establecimiento o construcción municipal, sino que se relaciona directamente con las actividades del servicio público de transmisión y distribución de energía eléctrica, materia cuya regulación corresponde a la Federación conforme a los preceptos constitucionales mencionados.</div>
<div> 92.     En efecto, como se explicó en el parámetro constitucional, la energía eléctrica se encuentra sujeta a un régimen constitucional y legal federal especializado, conforme al cual corresponde a la Federación la planeación y control del Sistema Eléctrico Nacional, así como la regulación, autorización, supervisión y vigilancia de las actividades del sector eléctrico, incluidas las relacionadas con la generación de energía eléctrica y las Centrales Eléctricas.</div>
<div> 93.     Lo anterior evidencia que el ámbito sobre el que legisla el Congreso local se vincula con la transmisión y distribución de energía eléctrica. Por ende, toda vez que conforme al marco constitucional referido se actualiza la competencia federal en relación con el control del sistema eléctrico nacional y la prestación del servicio público de transmisión y distribución, es dable reafirmar que se invade el ámbito de facultades reservadas para el Congreso de la Unión en cuanto a la regulación de esta materia.</div>
<div> 94.     En ese sentido, si bien los Municipios cuentan con facultades en materia hacendaria, administrativa, ambiental, de uso de suelo y licencias de funcionamiento, éstas no pueden ejercerse para establecer cobros específicos sobre edificaciones productoras de energía eléctrica, pues ello incide en infraestructura directamente vinculada con una materia reservada a la Federación.</div>
<div> 95.     No obsta que la disposición impugnada se ubique en un apartado relativo a servicios de control ambiental, ni que formalmente se presente como una licencia de funcionamiento municipal. Lo relevante es que el hecho imponible se actualiza precisamente por la existencia de una edificación productora de energía eléctrica, por cada aerogenerador o unidad, lo que evidencia que el cobro se vincula materialmente con infraestructura del sector eléctrico.</div>
<div> 96.     Permitir que cada Municipio establezca cobros anuales específicos respecto de edificaciones productoras de energía eléctrica generaría una fragmentación regulatoria incompatible con el diseño constitucional de la materia, pues dichas actividades e infraestructura requieren planeación nacional, criterios técnicos uniformes, continuidad, confiabilidad, supervisión especializada y control federal.</div>
<div> 97.     Por tanto, el numeral 1 de la fracción VII del artículo 34 impugnado invade la competencia exclusiva de la Federación en materia de energía eléctrica, al establecer una carga económica municipal sobre edificaciones productoras de energía eléctrica, materia cuya regulación, autorización, supervisión y verificación corresponde al ámbito federal.</div>','15','apartado','Numeral 1: Edificaciones productoras de energía eléctrica','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('a0c3dadb-66c1-5da6-9d9c-e0989ec5b048','bc88f14b-069f-56d9-b9a9-6456e808561d','Numerales 2 y 3: Edificaciones para extracción de gas natural y gas no asociado','<div> Numerales 2 y 3: Edificaciones para extracción de gas natural y gas no asociado<br/> </div>
<div> 98.     Los numerales 2 y 3 de la fracción VII del artículo 34 impugnado establecen un cobro anual, por cada unidad, por concepto de edificación para la extracción de gas natural y edificación para la extracción de gas no asociado, respectivamente.</div>
<div> 99.     Dichos supuestos normativos se ubican directamente en el ámbito de la industria de hidrocarburos, pues tienen como presupuesto material edificaciones destinadas a la extracción de gas natural y gas no asociado, términos definidos por la Ley del Sector Hidrocarburos(60) y que abarcan actividades que forman parte del núcleo constitucionalmente reservado a la Federación.</div>
<div> 100.    Como se explicó en el parámetro constitucional, la Constitución Federal declara a los hidrocarburos un área estratégica cuyo dominio, rectoría y regulación corresponden de manera exclusiva a la Federación, la cual tiene a su cargo la exploración y extracción de dichos recursos, así como la facultad para legislar y establecer contribuciones en esa materia a través del Congreso de la Unión.</div>
<div> 101.    Asimismo, este Alto Tribunal en sus precedentes ha reconocido que cuando las leyes de ingresos municipales prevén cobros por licencias de funcionamiento vinculadas con edificaciones o pozos destinados a la extracción de hidrocarburos, inciden en actividades que forman parte del núcleo de esa área estratégica, por lo que, al sujetar su realización al pago de gravámenes locales, invaden la competencia federal.</div>
<div> 102.    En el caso, los numerales 2 y 3 impugnados encuadran directamente en ese criterio, pues establecen cobros anuales por la expedición de licencias de funcionamiento respecto de edificaciones destinadas a la extracción de gas natural y gas no asociado. Por tanto, no se trata de un cobro municipal general o neutro, sino de una carga económica específicamente dirigida a actividades de extracción de hidrocarburos.</div>
<div> 103.    Lo anterior implica que en la hacienda municipal se enterarán montos con motivo de la expedición de tales autorizaciones por cualquiera de los supuestos ahí descritos, los cuales se relacionan directamente con las actividades de exploración y extracción de hidrocarburos, entendida la primera como la perforación de pozos con la finalidad última de identificar, descubrir y evaluar hidrocarburos en el subsuelo, y la segunda como la actividad o conjunto de actividades destinadas a la producción de hidrocarburos, incluyendo la perforación de pozos de producción y la construcción, localización, operación, uso, abandono y desmantelamiento de instalaciones para la producción, en términos de la Ley del Sector Hidrocarburos.(61)</div>
<div> 104.    Lo anterior evidencia que el ámbito sobre el que legisla el Congreso local se vincula con recursos que se ubican en yacimientos localizados en el subsuelo. Por ende, toda vez que conforme al cuarto párrafo del artículo 27 de la Constitución Federal, se actualiza la competencia federal en relación con la explotación de todos los minerales y sustancias que se encuentran en mantos, vetas o yacimientos, es dable reafirmar que se invade el ámbito de facultades reservadas para el Poder Legislativo Federal, en términos del artículo 73, fracción XXIX, numeral 2, del propio Ordenamiento Fundamental.</div>
<div> 105.    Resulta aplicable la jurisprudencia P./J. 61/2026 (12a.)(62), de texto:</div>
<div> "HIDROCARBUROS. EL COBRO DE DERECHOS MUNICIPALES POR LA EXPEDICIÓN DE LICENCIAS DE FUNCIONAMIENTO VINCULADAS CON SU EXPLORACIÓN O EXTRACCIÓN, INVADE LA COMPETENCIA EXCLUSIVA DE LA FEDERACIÓN.</div>
<div> Hechos: El Poder Ejecutivo Federal promovió controversia constitucional contra los Poderes Ejecutivo y Legislativo del Estado de Coahuila de Zaragoza, en la que demandó la invalidez, entre otros, del artículo 20, fracción I, numerales 1, 3, 4, 5 y 6, de la Ley de Ingresos para el Municipio de Ocampo, del Ejercicio Fiscal 2025, que establece el cobro de derechos por la expedición de licencia de funcionamiento vinculadas con edificaciones para la extracción del gas de lutitas o gas shale, gas natural y gas no asociado, así como por la perforación de pozos verticales y direccionales en el área específica a yacimientos convencionales (roca reservorio) en trampas estructurales donde se encuentre el hidrocarburo, y por la perforación de pozos para la extracción de cualquier hidrocarburo.</div>
<div> En la demanda se argumentó que tales preceptos invaden la competencia exclusiva de la Federación en materia de hidrocarburos, prevista en los artículos 25, párrafo quinto, 27, párrafos cuarto, sexto y séptimo, 28, párrafo cuarto, y 73, fracciones X y XXIX, numeral 2o., de la Constitución Federal.</div>
<div> Criterio jurídico: Las normas que prevén el cobro de derechos municipales por la expedición de licencias de funcionamiento vinculadas con la exploración o extracción de hidrocarburos son inconstitucionales, al tratarse de un área estratégica cuya regulación está reservada de manera exclusiva a la Federación para legislar en la materia.</div>
<div> Justificación: De los artículos 25, párrafo quinto; 27, párrafos cuarto, sexto y séptimo; 28, párrafo cuarto, y 73, fracciones X y XXIX, numeral 2o., de la Constitución Política de los Estados Unidos Mexicanos, se desprende que los hidrocarburos constituyen un área estratégica cuyo dominio, rectoría y regulación corresponden de manera exclusiva a la Federación, la cual tiene a su cargo la exploración y extracción de dichos recursos, así como la facultad para legislar y establecer contribuciones en esa materia a través del Congreso de la Unión.</div>
<div> Cuando en las leyes de ingresos municipales aprobadas por los Congresos Locales se prevé el cobro de derechos por la expedición de licencias de funcionamiento vinculadas con edificaciones para la extracción del gas de lutitas o gas shale, gas natural y gas no asociado, así como por la perforación de pozos verticales y direccionales en el área específica a yacimientos convencionales (roca reservorio) en trampas estructurales donde se encuentre el hidrocarburo, y por la perforación de pozos para la extracción de cualquier hidrocarburo, inciden en actividades que forman parte del núcleo de esa área estratégica. Por ello, al sujetar su realización al pago de gravámenes locales, tales preceptos resultan inconstitucionales, ya que las entidades federativas invaden la competencia reservada de manera exclusiva a la Federación.</div>
<div> Controversia constitucional 112/2025. Poder Ejecutivo Federal. 17 de septiembre de 2025. Unanimidad de nueve votos de las personas Ministras Sara Irene Herrerías Guerra, Irving Espinosa Betanzo, María Estela Ríos González, Yasmín Esquivel Mossa, Lenia Batres Guadarrama por consideraciones distintas, Loretta Ortiz Ahlf quien formuló voto concurrente, Giovanni Azael Figueroa Mejía con consideraciones adicionales y formuló voto concurrente, Arístides Rodrigo Guerrero García y Presidente Hugo Aguilar Ortiz quien formuló voto aclaratorio. Ponente: Loretta Ortiz Ahlf. Secretario: Johan Martín Escalante Escalante."</div>
<div> 106.    A todo lo expuesto no pasa inadvertido que el Poder Legislativo local sostenga que la norma impugnada corresponde al cobro de derechos por licencias de funcionamiento en materia de control ambiental. Sin embargo, como ya se determinó, los conceptos gravados se relacionan directamente con materias de competencia federal, tanto en energía eléctrica como en hidrocarburos. Por ello, aun cuando formalmente se presenten como licencias municipales o servicios de control ambiental, materialmente inciden en actividades e infraestructura sujetas a regulación, autorización, supervisión y verificación federal.</div>
<div> 107.    Finalmente, al haberse alcanzado la pretensión de la parte actora respecto a la invasión a la competencia federal, resulta innecesario el estudio de los restantes conceptos de invalidez, pues su examen en nada cambiaría la conclusión alcanzada. Sirve de apoyo la jurisprudencia P./J. 100/99(63), emitida por el Pleno de este Alto Tribunal, de rubro: "CONTROVERSIA CONSTITUCIONAL. ESTUDIO INNECESARIO DE CONCEPTOS DE INVALIDEZ."</div>
<div> 108.    En consecuencia, lo procedente es declarar la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial del Gobierno local el veintitrés de diciembre de dos mil veinticinco, por invadir la competencia exclusiva de la Federación en materia de energía eléctrica e hidrocarburos.</div>','16','apartado','Numerales 2 y 3: Edificaciones para extracción de gas natural y gas no asociado','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('3dba71d7-dadb-5e6d-8b99-9ab8975992f1','bc88f14b-069f-56d9-b9a9-6456e808561d','VII. EFECTOS','<div> VII. EFECTOS<br/> </div>
<div> 109.    El artículo 73(64), en relación con los artículos 41, fracción IV, 43, 44 y 45(65) de la Ley Reglamentaria, señala que las sentencias deben contener los alcances y los efectos de éstas, así como fijar con precisión los órganos obligados a cumplirlas, las normas generales respecto de las cuales opere y todos aquellos elementos necesarios para su plena eficacia en el ámbito que corresponda; además, se debe fijar la fecha a partir de la cual la sentencia producirá sus efectos y éstos deberán extenderse a todas aquellas normas cuya validez dependa de la propia norma invalidada.</div>
<div> 110.    Declaratoria de invalidez: Se declara la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial del Gobierno local el veintitrés de diciembre de dos mil veinticinco.</div>
<div> 111.    Fecha en que surtirá efectos la invalidez. Esta declaratoria de invalidez surtirá sus efectos a partir de la notificación de los puntos resolutivos al Congreso del Estado de Coahuila de Zaragoza.</div>
<div> 112.    Notificación al Municipio. Finalmente, deberá notificarse la presente sentencia al Municipio involucrado, por ser la autoridad encargada de la aplicación de la ley de ingresos cuya disposición ha sido invalidada.</div>','17','apartado','VII. EFECTOS','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('bfd725b9-64ff-5259-884b-9cdb8b3d2baa','bc88f14b-069f-56d9-b9a9-6456e808561d','VIII. DECISIÓN','<div> VIII. DECISIÓN<br/> </div>
<div> Por lo expuesto y fundado, el Tribunal Pleno de la Suprema Corte de Justicia de la Nación resuelve:</div>','18','apartado','VIII. DECISIÓN','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('12063638-a16e-538e-ae97-dee0f2ffd7d0','bc88f14b-069f-56d9-b9a9-6456e808561d','Resolutivo PRIMERO','<div> PRIMERO. Es procedente y fundada la presente controversia constitucional.</div>','19','apartado','Resolutivo PRIMERO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('bb8c3252-4a66-51a7-b5be-3dc2cb47786d','bc88f14b-069f-56d9-b9a9-6456e808561d','Resolutivo SEGUNDO','<div> SEGUNDO. Se declara la invalidez del artículo 34, fracción VII, numerales 1, 2 y 3, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el Ejercicio Fiscal 2026, publicada en el Periódico Oficial del Gobierno local el veintitrés de diciembre de dos mil veinticinco, la cual surtirá efectos a partir de la notificación de estos puntos resolutivos al Congreso del Estado de Coahuila de Zaragoza, por las razones y en los términos precisados en los apartados VI y VII de esta sentencia.</div>','20','apartado','Resolutivo SEGUNDO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('96bd8d1c-ec01-5471-8880-f570c9bcdc52','bc88f14b-069f-56d9-b9a9-6456e808561d','Resolutivo TERCERO','<div> TERCERO. Publíquese esta resolución en el Diario Oficial de la Federación, en el Periódico Oficial del Gobierno del Estado de Coahuila de Zaragoza y en el Semanario Judicial de la Federación y su Gaceta.</div>','21','apartado','Resolutivo TERCERO','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('14c011ed-8062-5e4b-9d06-9b20e63edf67','bc88f14b-069f-56d9-b9a9-6456e808561d','Notificaciones, votación y firmas','<div> Notifíquese; haciéndolo por oficio a las partes, en su oportunidad devuélvase el expediente a la Sección de Trámite de Controversias Constitucionales y de Acciones de Inconstitucionalidad para los efectos legales a que haya lugar, y archívese como asunto concluido.</div>
<div> Así lo resolvió el Pleno de la Suprema Corte de Justicia de la Nación por unanimidad de ocho votos de las personas Ministras Herrerías Guerra; Espinosa Betanzo; Ríos González; Esquivel Mossa; Batres Guadarrama; Ortiz Ahlf; Figueroa Mejía, por consideraciones distintas en el tema de energía eléctrica(66); y Presidente Aguilar Ortiz, separándose de los párrafos del 72 al 87 y del 90 al 108. La señora Ministra Batres Guadarrama anunció voto concurrente.</div>
<div> El señor Ministro Arístides Rodrigo Guerrero García no asistió a la sesión de cuatro de agosto de dos mil veintiséis previo aviso a la Presidencia.</div>
<div> El señor Ministro Presidente Aguilar Ortiz declaró que el asunto se resolvió en los términos propuestos.</div>
<div> Firman el Ministro Presidente y la Ministra Ponente, con el Secretario General de Acuerdos, quien autoriza y da fe.</div>
<div> Presidente, Ministro Hugo Aguilar Ortiz.- (Esta sentencia se suscribe con Firma Electrónica Certificada del Poder Judicial de la Federación [FIREL]).- Ponente, Ministra Yasmín Esquivel Mossa.- (Esta sentencia se suscribe con Firma Electrónica Certificada del Poder Judicial de la Federación [FIREL]).- Secretario General de Acuerdos, Daniel Álvarez Toledo.- (Esta sentencia se suscribe con Firma Electrónica Certificada del Poder Judicial de la Federación [FIREL]).</div>','22','apartado','Notificaciones, votación y firmas','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('9524ba33-9a32-569a-b221-7534b107ead2','bc88f14b-069f-56d9-b9a9-6456e808561d','Certificación de la sentencia','<div> DANIEL ÁLVAREZ TOLEDO, SECRETARIO GENERAL DE ACUERDOS DE LA SUPREMA CORTE DE JUSTICIA DE LA NACIÓN: CERTIFICA: Que la presente copias fotostática constante de treinta y un fojas útiles, en las que se cuentan esta certificación, concuerda fiel y exactamente con el original firmado electrónicamente de la sentencia emitida en la controversia constitucional 120/2026, promovida por el Poder Ejecutivo Federal, dictada por el Pleno de la Suprema Corte de Justicia de la Nación en su sesión del cuatro de agosto de dos mil veintiséis. Se certifica con la finalidad de que se publique en el Diario Oficial de la Federación.- Ciudad de México, a cinco de octubre de dos mil veintiséis.- Rúbrica.</div>','23','apartado','Certificación de la sentencia','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('f14d4d0b-0c80-59e4-8d49-0c2ccc9804f1','bc88f14b-069f-56d9-b9a9-6456e808561d','Voto concurrente de la ministra Lenia Batres Guadarrama','<div> VOTO CONCURRENTE QUE FORMULA LA MINISTRA LENIA BATRES GUADARRAMA EN LA CONTROVERSIA CONSTITUCIONAL 120/2026</div>
<div> El Poder Ejecutivo Federal promovió controversia constitucional en contra de los Poderes Ejecutivo y Legislativo del estado de Coahuila de Zaragoza, mediante la cual demandó la invalidez del artículo 34, fracción VII, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el ejercicio fiscal 2026, publicada en el Periódico Oficial de dicha entidad federativa, el veintitrés de diciembre de dos mil veinticinco.</div>
<div> Al respecto, el Pleno resolvió declarar la invalidez del artículo 34, fracción VII, de la Ley impugnada, que establece el pago de derechos por la expedición de licencia de funcionamiento de las centrales productoras de energía termoeléctrica, térmica solar, hidroeléctrica, eólica, fotovoltaica, aerogeneradores o similares, así como de las edificaciones para la extracción del gas natural y gas no asociado.</div>
<div> 1. Razones de la mayoría</div>
<div> En sesión celebrada el cuatro de agosto de dos mil veintiséis, el Pleno de esta Suprema Corte de Justicia de la Nación (SCJN) aprobó el proyecto por unanimidad de ocho votos de las personas Ministras Herrerías Guerra, Espinosa Betanzo, Ríos González, Esquivel Mossa, Batres Guadarrama con anuncio de voto concurrente, Ortiz Ahlf, Figueroa Mejía, por consideraciones distintas en el tema de energía eléctrica y del Presidente Aguilar Ortiz, apartándose de los párrafos 72 a 87 y 90 a 108.</div>
<div> La mayoría de los integrantes del Pleno de la SCJN consideraron que el artículo 34, fracción VII, de la Ley de Ingresos del Municipio de Castaños, Coahuila de Zaragoza, para el ejercicio fiscal 2026, invade en el ámbito competencial de la Federación, pues la licencia de funcionamiento prevista en dicho precepto constituye una condición necesaria para llevar a cabo actividades que, conforme al régimen constitucional de distribución de competencias, se encuentran sujetas a regulación federal.</div>
<div> 2. Razones de la emisión del voto</div>
<div> Si bien comparto el sentido del proyecto, emito el presente voto concurrente para realizar las siguientes aclaraciones:</div>
<div> Coincido con el proyecto en que el artículo impugnado invade la esfera de competencias de la Federación, porque, en términos de la Constitución Política de los Estados Unidos Mexicanos (CPEUM), sólo el Congreso de la Unión tiene facultades para legislar en toda la República en materia de hidrocarburos y energía eléctrica.</div>
<div> En esos términos, aun cuando los municipios tienen atribuciones constitucionales para emitir diversas autorizaciones en materia urbanística, administrativa, ambiental o de protección civil, éstas no pueden configurarse de manera que el hecho imponible recaiga sobre actividades de exploración o extracción de hidrocarburos, ni sobre proyectos o infraestructura destinados a la generación, transmisión o distribución de energía eléctrica, ni calcularse con base en elementos propios de dichas actividades.</div>
<div> En este caso, las normas impugnadas no constituyen un cobro por el funcionamiento de cualquier establecimiento o construcción municipal, sino que se relaciona directamente con las actividades cuya regulación corresponde de manera exclusiva a la Federación. Por un lado, respecto de la licencia para el funcionamiento de las edificaciones productoras de energía, la tarifa se cobra en función del número de aerogeneradores o unidades productoras de energía, lo que hace evidente que el cobro no se vincula con las competencias municipales en materia de establecimientos mercantiles o desarrollo urbano, sino directamente con la generación de energía eléctrica. Por otro lado, respecto de las licencias para el funcionamiento de las edificaciones para la extracción de gas, la tarifa igualmente se cobra en función de cada unidad de extracción, es decir, se trata de una carga económica específicamente dirigida a las actividades de extracción de hidrocarburos.</div>
<div> No obstante, cabe aclarar que los Municipios sí tienen competencia para expedir licencias de funcionamiento, incluso respecto de establecimientos destinados a la exploración y extracción de hidrocarburos, siempre que dichas autorizaciones se limiten a la competencia que la CPEUM concede a ese orden de gobierno en materia de desarrollo urbano, uso de suelo, construcciones, administración de la vía pública, protección civil e imagen urbana.</div>
<div> Sin embargo, en este caso, la norma prevé una licencia de funcionamiento cuyo objeto es en sí mismo una actividad reservada a la federación: la producción de energía y la extracción de hidrocarburos, por lo que procede declarar su inconstitucionalidad.</div>
<div> Además, los términos en los que se encuentra redactada vulneran el principio de seguridad jurídica al generar un margen de ambigüedad en su interpretación, pues no está claro si la licencia es por el funcionamiento de la edificación, por la actividad que realiza o por la edificación en sí misma.</div>
<div> Ministra Lenia Batres Guadarrama.- Este voto se suscribe con Firma Electrónica Certificada del Poder Judicial de la Federación [FIREL]).</div>','24','apartado','Voto concurrente de la ministra Lenia Batres Guadarrama','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('d98e969e-9893-506f-9ad8-04088b0e0a8a','bc88f14b-069f-56d9-b9a9-6456e808561d','Certificación del voto concurrente','<div> DANIEL ÁLVAREZ TOLEDO, SECRETARIO GENERAL DE ACUERDOS DE LA SUPREMA CORTE DE JUSTICIA DE LA NACIÓN: CERTIFICA: Que la presente copia fotostática constante de dos fojas útiles, en la que se encuentra esta certificación concuerda fiel y exactamente con el original firmado electrónicamente voto concurrente de la señora Ministra Lenia Batres Guadarrama, formulado en relación con la sentencia del cuatro de agosto de dos mil veintiséis, dictada por el Pleno de la Suprema Corte de Justicia de la Nación en la Controversia constitucional 120/2026, promovida por el Poder Ejecutivo Federal. Se certifica con la finalidad de que se publique en el Diario Oficial de la Federación.- Ciudad de México, a catorce de octubre de dos mil veintiséis.- Rúbrica.</div>','25','apartado','Certificación del voto concurrente','Controversia constitucional 120/2026');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,capitulo_nombre,titulo_nombre) VALUES ('49152f8d-263c-5062-afb4-ec466e758932','bc88f14b-069f-56d9-b9a9-6456e808561d','Notas al pie de la sentencia','<div> 1     Página 56 de la versión digitalizada del escrito de demanda.</div>
<div> 2     Página 27 de la versión digitalizada del escrito de manifestaciones presentado por la Cámara de Senadores del Congreso de la Unión.</div>
<div> 3     Página 7 de la versión digitalizada del escrito de manifestaciones presentado por la Cámara de Diputados del Congreso de la Unión.</div>
<div> 4     Página 4 de la versión digitalizada de la contestación del Poder Ejecutivo del Estado de Coahuila de Zaragoza.</div>
<div> 5     Página 28 de la versión digitalizada de la contestación del Poder Legislativo del Estado de Coahuila de Zaragoza.</div>
<div> 6     De conformidad con el artículo 18 del Reglamento de Sesiones de la Suprema Corte de Justicia de la Nación y de Integración de las Listas de Asuntos con Proyecto de Resolución.</div>
<div> 7     Constitución Federal.</div>
<div> Artículo 105. La Suprema Corte de Justicia de la Nación conocerá, en los términos que señale la ley reglamentaria, de los asuntos siguientes: [...]</div>
<div> I. De las controversias constitucionales que, sobre la constitucionalidad de las normas generales, actos u omisiones, con excepción de las que se refieran a la materia electoral, se susciten entre: [...]</div>
<div> a) La Federación y una entidad federativa; [...]</div>
<div> 8     Ley Reglamentaria.</div>
<div> Artículo 1o. La Suprema Corte de Justicia de la Nación conocerá y resolverá con base en las disposiciones del presente Título, las controversias constitucionales en las que se hagan valer violaciones a la Constitución Política de los Estados Unidos Mexicanos, así como las acciones de inconstitucionalidad a que se refieren las fracciones I y II del artículo 105 de la Constitución Política de los Estados Unidos Mexicanos. A falta de disposición expresa, se estará a las prevenciones del Código Nacional de Procedimientos Civiles y Familiares.</div>
<div> 9     Ley Orgánica del Poder Judicial de la Federación.</div>
<div> Artículo 16. La Suprema Corte de Justicia de la Nación conocerá:</div>
<div> I. De las controversias constitucionales y acciones de inconstitucionalidad a que se refieren las fracciones I y II del artículo 105 de la Constitución Política de los Estados Unidos Mexicanos. La admisión de controversias constitucionales y acciones de inconstitucionalidad planteadas respecto de normas generales no dará lugar en ningún caso a la suspensión de la norma cuestionada; [...]</div>
<div> 10    Acuerdo General 2/2025 (12a).</div>
<div> SEGUNDO. Competencia reservada del Pleno de la SCJN. La SCJN conservará para su resolución: [...]</div>
<div> I. Las controversias constitucionales previstas en el artículo 105, fracción I, de la CPEUM, así como los recursos interpuestos en éstas. (...)</div>
<div> 11    Ley Reglamentaria.</div>
<div> Artículo 41. Las sentencias deberán contener:</div>
<div> I. La fijación breve y precisa de las normas generales, actos u omisiones objeto de la controversia y, en su caso, la apreciación de las pruebas conducentes a tenerlos o no por demostrados; [...].</div>
<div> 12    Jurisprudencia P./J. 98/2009, de texto: CONTROVERSIAS CONSTITUCIONALES. REGLAS A LAS QUE DEBE ATENDER LA SUPREMA CORTE DE JUSTICIA DE LA NACIÓN PARA LA FIJACIÓN DE LA NORMA GENERAL O ACTO CUYA INVALIDEZ SE DEMANDA EN EL DICTADO DE LA SENTENCIA. El artículo 41, fracción I, de la Ley Reglamentaria de las Fracciones I y II del Artículo 105 de la Constitución Política de los Estados Unidos Mexicanos, establece que las sentencias deberán contener la fijación breve y precisa de las normas generales o actos objeto de la controversia y, en su caso, la apreciación de las pruebas conducentes a tenerlos o no por demostrados; asimismo, la Suprema Corte de Justicia de la Nación ha sostenido que para lograr tal fijación debe acudirse a la lectura íntegra de la demanda, apreciación que deberá realizar sin atender a los calificativos que en su enunciación se hagan sobre su constitucionalidad o inconstitucionalidad en virtud de que tales aspectos son materia de los conceptos de invalidez. Sin embargo, en algunos casos ello resulta insuficiente y ante tal situación deben armonizarse, además, los datos que sobre los reclamos emanen del escrito inicial, interpretándolos en un sentido congruente con todos sus elementos e incluso con la totalidad de la información del expediente del juicio, de una manera tal que la fijación de las normas o actos en la resolución sea razonable y apegada a la litis del juicio constitucional, para lo cual debe atenderse preferentemente a la intención del promovente y descartando manifestaciones o imprecisiones que generen oscuridad o confusión. Esto es, el Tribunal Constitucional deberá atender a lo que quiso decir la parte promovente de la controversia y no a lo que ésta dijo en apariencia, pues sólo de este modo podrá lograrse congruencia entre lo pretendido y lo resuelto., publicada en el Semanario Judicial de la Federación y su Gaceta, Novena Época, Tomo XXX, julio de 2009, página 1536, registro 166985.</div>
<div> 13    Ley Reglamentaria de la materia.</div>
<div> Artículo 21. El plazo para la interposición de la demanda será: [...]</div>
<div> II. Tratándose de normas generales, de treinta días contados a partir del día siguiente a la fecha de su publicación, o del día siguiente al en que se produzca el primer acto de aplicación de la norma que dé lugar a la controversia, y [...]</div>
<div> 14    Ley Reglamentaria.</div>
<div> Artículo 2o. Para los efectos de esta ley, se considerarán como hábiles todos los días que determine la Ley Orgánica del Poder Judicial de la Federación.</div>
<div> Ley Orgánica del Poder Judicial de la Federación.</div>
<div> Artículo 3. La Suprema Corte de Justicia de la Nación tendrá cada año dos periodos de sesiones: el primero comenzará el primer día hábil del mes de enero y terminará el último día hábil de la primera quincena del mes de julio, y el segundo comenzará el primer día hábil del mes de agosto y terminará el último día hábil de la primera quincena del mes de diciembre.</div>
<div> Artículo 229. En los órganos del Poder Judicial de la Federación, se considerarán como días inhábiles los sábados y domingos, el 1o. de enero, 5 de febrero, 21 de marzo, 1o. de mayo, 14 y 16 de septiembre y 20 de noviembre, durante los cuales no se practicarán actuaciones judiciales, salvo en los casos expresamente consignados en la ley.</div>
<div> Acuerdo General Plenario 18/2013.</div>
<div> PRIMERO. Para efectos del cómputo de los plazos procesales en los asuntos de la competencia de la Suprema Corte de Justicia de la Nación, se considerarán como días inhábiles: [...]</div>
<div> c) Los lunes en que por disposición de la Ley Federal del Trabajo deje de laborarse; [...]</div>
<div> e) El cinco de febrero; [...].</div>
<div> Ley Federal del Trabajo.</div>
<div> Artículo 74. Son días de descanso obligatorio. [...]</div>
<div> II, El primer lunes de febrero en conmemoración del 5 de febrero; [...].</div>
<div> 15    Página 56 de la versión digitalizada del escrito de demanda.</div>
<div> 16    Ley Reglamentaria.</div>
<div> Artículo 10. Tendrán el carácter de parte en las controversias constitucionales:</div>
<div> I. Como actor, la entidad, poder u órgano que promueva la controversia;</div>
<div> (REFORMADA, D.O.F. 7 DE JUNIO DE 2021)</div>
<div> II. Como demandada o demandado, la entidad, poder u órgano que hubiere emitido y promulgado la norma general, pronunciado el acto o incurrido en la omisión que sea objeto de la controversia;</div>
<div> (REFORMADA [N. DE E. REPUBLICADA], D.O.F. 3 DE ABRIL DE 2025)</div>
<div> III. Como tercero o terceros interesados, las entidades, poderes u órganos a que se refiere la fracción I del artículo 105 de la Constitución Política de los Estados Unidos Mexicanos, que, sin tener el carácter de actores o demandados, pudieran resultar afectados por la sentencia que llegare a dictarse, y</div>
<div> (REFORMADA, D.O.F. 3 DE ABRIL DE 2025)</div>
<div> IV. La persona titular de la Fiscalía General de la República.; [...].</div>
<div> Artículo 11. El actor, el demandado y, en su caso, el tercero interesado deberán comparecer a juicio por conducto de las personas funcionarias que, en términos de las normas que les rigen, estén facultadas para representarlos. En todo caso, se presumirá que quien comparezca a juicio goza de la representación legal y cuenta con la capacidad para hacerlo, salvo prueba en contrario. [...].</div>
<div> La persona titular de la Presidencia de los Estados Unidos Mexicanos será representado o representada por el secretario o secretaria de estado, por el jefe o jefa del departamento administrativo o por el Consejero o la Consejera Jurídica del Gobierno, conforme lo determine el propio Presidente o Presidenta, y considerando para tales efectos las competencias establecidas en la ley. El acreditamiento de la personalidad de estas personas servidoras públicas y su suplencia se harán en los términos previstos en las leyes o reglamentos interiores que correspondan.</div>
<div> 17    Foja 57 de la versión digitalizada del escrito de demanda.</div>
<div> 18    Tesis 2a. XLVII/2003, de texto: El Ejecutivo Federal constituye un Poder de la Federación a través del cual, en términos de lo previsto en el artículo 41 de la Constitución Política de los Estados Unidos Mexicanos, se ejerce la soberanía popular respecto de la esfera de atribuciones reservada a esa entidad política; por tanto, en virtud de que en la propia Norma Fundamental no existe disposición en contrario al tenor de la cual expresamente se confiera a alguno de los Poderes de la Unión la representación de la Federación para promover una controversia constitucional, debe estimarse que el Poder Ejecutivo Federal está legitimado procesalmente para promover un juicio de esa naturaleza en nombre de la Federación; además, si se toma en cuenta que dicho Poder es un órgano unipersonal encarnado por el Presidente de la República, es evidente que éste, según lo dispuesto en el artículo 11, párrafo primero, de la Ley Reglamentaria de las Fracciones I y II del Artículo 105 de la Constitución Federal, está legitimado para promover juicios de esa índole, por sí, o bien a través del secretario de Estado o el consejero jurídico del Gobierno que determine el propio Presidente, de conformidad con el último párrafo del artículo 11 citado., publicada en el Semanario Judicial de la Federación y su Gaceta, Novena Época, Tomo XVII, Abril de 2003, página 862, registro 184512.</div>
<div> 19    Página 5 de la versión digitalizada del escrito de contestación a la demanda del Poder Ejecutivo del Estado de Coahuila de Zaragoza.</div>
<div> 20    Ley Orgánica de la Administración Pública del Estado de Coahuila de Zaragoza.</div>
<div> Artículo 21. A la Secretaría de Gobierno le corresponde el despacho de los siguientes asuntos:</div>
<div> [...]</div>
<div> XXX. Coordinar y apoyar la defensa jurídica de las dependencias y entidades de la administración pública, en los juicios de amparo en los que se señale como responsables a las autoridades del Poder Ejecutivo y representar al Titular del Ejecutivo, en todo tipo de controversias, juicios o acciones de inconstitucionalidad en que éste sea parte con cualquier carácter, esta facultad es delegable; [...]</div>
<div> ; y [...];</div>
<div> 21    Reglamento Interior de la Secretaría de Gobierno del Estado de Coahuila de Zaragoza.</div>
<div> Artículo 5. Al frente de la Secretaría habrá un Secretario, quién tendrá a su cargo el despacho de los asuntos que las leyes le asignan, además de aquellas que le sean encomendadas y para tal efecto, se auxiliará de las siguientes unidades administrativas: [...]</div>
<div> VII. La Consejería Jurídica; [...].</div>
<div> Artículo 25. Corresponde a la o el titular de la Consejería Jurídica, además de las consignadas en el artículo 10 de este reglamento, las facultades y obligaciones siguientes: [...]</div>
<div> VIII. Representar al Ejecutivo y al Secretario, en las acciones y controversias a que se refiere el artículo 105 de la Constitución Política de los Estados Unidos Mexicanos, así como en los demás juicios en que éste intervenga con cualquier carácter; y asesorar a las dependencias que concurran a alguno de estos procesos; [...].</div>
<div> 22    Página 29 de la versión digitalizada del escrito de contestación a la demanda del Poder Legislativo del Estado de Coahuila de Zaragoza.</div>
<div> 23    Ley Orgánica del Congreso del Estado Independiente Libre y Soberano de Coahuila de Zaragoza.</div>
<div> Artículo 48. La o el Presidente de la Mesa Directiva del Congreso, tiene las facultades y obligaciones siguientes:</div>
<div> I. Representar legalmente al Congreso del Estado y a la Junta de Gobierno ante toda clase de autoridades, en materia administrativa, penal, civil, fiscal o laboral, así como en materia de amparo y en los demás asuntos en los que sea parte el Congreso. La o el Presidente podrá delegar esta representación en cualquiera de los titulares de los órganos técnicos al Congreso, otorgando el poder legal correspondiente. [...],</div>
<div> 24    Ley Orgánica del Congreso General de los Estados Unidos Mexicanos.</div>
<div> Artículo 22.</div>
<div> 1. El Presidente de la Mesa Directiva es el Presidente de la Cámara de Diputados y expresa su unidad. Garantiza el fuero constitucional de los diputados y vela por la inviolabilidad del Recinto Legislativo. [...].</div>
